INSERT INTO diseases(public_id, data) VALUES ('disease_0004', $seed_json$
{"id":"disease_0004","name":"ルチゼルン","name_kana":"ルチゼルン","name_english":"rchi'Zelln","icd10_chapter":"chapter_i","medical_department":["infectious_disease","otolaryngology"],"chronicity":"acute","infectious":true,"synonyms":["ヒショウェウレ","カモリ","アレトロウル"],"summary":"ルチゼルンは病原体関連疾患に分類される疾患群で、トタを主訴に受診する例が多い。確定診断には**病原体検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":5.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 5 (架空)"},"onset_age_range":{"min_age_years":56,"max_age_years":69,"label":"56-69 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["飛沫伝播","経口感染への曝露","経口感染への曝露"]},"etiology":"ルチゼルンは感染性疾患に分類される疾患群で、トイムリョクを主訴に受診する例が多い。確定診断には**炎症反応検査** を用いる。 (架空)","symptoms":{"main_symptoms":["息切れ","発熱","食欲不振","疼痛","息切れ"],"associated_symptoms":["悪心","発汗"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 病原体検査の主要異常\n- 補助項目: 感染症評価スコアの上昇\n(架空)","炎症反応検査 による所見と発熱炎症所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"supporting":["病原体検査 による所見と感染症に整合する身体所見 の組み合わせで判定する。除外診断として感染症に類似する別疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**発熱炎症を示す中核所見** を満たし、かつ5 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**感染症に特徴的な検査異常** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"MRI検査","category":"blood_test","typical_finding":"ワア (架空)","reference_range":"オグンレイ (架空)"},{"name":"MRI検査","category":"interview","typical_finding":"モクオン (架空)","reference_range":"ショウチョン (架空)"},{"name":"血液生化学検査","category":"imaging","typical_finding":"ワア (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["チルフウム","シイン","ペルマド"],"complications":["デスエアルトイ","デスパイ","シアル"],"treatments":{"pharmacological":[{"drug_category":"トゥルククウルレ","drug_ids":[],"indication":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は再燃予防と感染対策による維持療法を継続する。 (架空)","notes":"標準治療は感染症標準治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から14 週間 後に効果判定を行う。 (架空)"},{"drug_category":"クウスメ","drug_ids":[],"indication":"急性期には感染症急性期プロトコルを実施し、安定期へ移行後は再燃予防と感染対策による維持療法を継続する。 (架空)","notes":"標準治療は感染症標準治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から14 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ジオエナ","ワチウェ"],"description":"標準治療は抗微生物薬適正使用を中心とし、症状に応じて感染管理指導を併用する。治療開始から24 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["ラウセオテ","ワチウェ"],"description":"抗微生物薬適正使用 を第一選択とする。効果不十分例では薬剤感受性に基づく変更を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"抗微生物薬適正使用 を第一選択とする。効果不十分例では薬剤感受性に基づく変更を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の感染症再燃率 は**約 80.5%** と報告される (架空)。","prevention":["予防接種の検討"],"related_drug_ids":["drug_0068","drug_0105"],"related_disease_ids":["disease_0078","disease_0000"],"revised_at":"2026-04-19","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0005', $seed_json$
{"id":"disease_0005","name":"エイデンヴァニ","name_kana":"エイデンヴァニ","name_english":"Eiden'Vani","icd10_chapter":"chapter_i","medical_department":["infectious_disease","pediatrics"],"chronicity":"acute","infectious":true,"synonyms":["イサ","リアルトエ","オフィシャ"],"summary":"エイデンヴァニは、伝播経路に関連する症状を特徴とする急性疾患である。小児に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":40.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 40 (架空)"},"onset_age_range":{"min_age_years":38,"max_age_years":58,"label":"38-58 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["空気感染への曝露","院内接触歴"]},"etiology":"エイデンヴァニは免疫応答系に発現する病態で、急性発症の経過を呈する。推定有病率は人口 10 万対 37 (架空)。","symptoms":{"main_symptoms":["倦怠感","動悸","体重減少"],"associated_symptoms":["めまい","発汗","不眠"],"onset_pattern":"acute"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 感染症に特徴的な検査異常\n- 補助項目: 感染症評価スコアの上昇\n(架空)","感染症評価パネル による所見と感染症に整合する身体所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**発熱炎症を示す中核所見** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["炎症反応検査 による所見と感染症に整合する身体所見 の組み合わせで判定する。除外診断として非感染性炎症を除外することが必要。 (架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 発熱炎症を示す中核所見\n- 補助項目: 炎症反応検査の補助所見\n(架空)"},"required_exams":[{"name":"内視鏡検査","category":"blood_test","typical_finding":"ヒロト (架空)","reference_range":"スイネイ (架空)"},{"name":"心電図","category":"pathology","typical_finding":"マクオ (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["ラウセオルンクフ"],"complications":["シバル","イエヴィルソイ","ドンイリョク"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","ジオエナ"],"description":"感染症管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は感染症科へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"感染症管理 を第一選択とする。効果不十分例では薬剤感受性に基づく変更を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"抗微生物薬適正使用 を第一選択とする。効果不十分例では薬剤感受性に基づく変更を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"未治療例では全身炎症の遷延を合併する例が散見されるため、定期的な炎症反応検査 による経過観察が重要である。 (架空)","prevention":["接触機会の低減","手指衛生の徹底"],"related_drug_ids":["drug_0069"],"related_disease_ids":["disease_0025"],"revised_at":"2026-04-18","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
