INSERT INTO diseases(public_id, data) VALUES ('disease_0007', $seed_json$
{"id":"disease_0007","name":"ルイロジ","name_kana":"ルイロジ","name_english":"Rui'roji","icd10_chapter":"chapter_ii","medical_department":["internal_medicine","orthopedics"],"chronicity":"chronic","infectious":false,"synonyms":["アンクギエ"],"summary":"ルイロジは、異常細胞増殖を特徴とする亜急性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":8.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 8 (架空)"},"onset_age_range":{"min_age_years":31,"max_age_years":41,"label":"31-41 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["家族歴","家族歴"]},"etiology":"ルイロジは、組織浸潤傾向を特徴とする慢性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["頭痛","体重減少","動悸"],"associated_symptoms":["浮腫","下痢","浮腫"],"onset_pattern":"subacute"},"diagnostic_criteria":{"required":["腫瘍マーカー検査 による所見と腫瘍性疾患に整合する身体所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","腫瘍マーカー検査 による所見と腫瘍組織機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**病理組織検査の主要異常** を満たし、かつ5 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["病理組織検査 による所見と腫瘍組織機能の変化 の組み合わせで判定する。除外診断として良性腫瘍を除外することが必要。 (架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 病理組織検査の主要異常\n- 補助項目: 腫瘍性疾患評価スコアの上昇\n(架空)"},"required_exams":[{"name":"CT検査","category":"pathology","typical_finding":"ヒロト (架空)","reference_range":"スイネイ (架空)"},{"name":"単純X線撮影","category":"pathology","typical_finding":"マクオ (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":{"grading_system":"ライオル","grades":[{"label":"クオル","criteria":"重症度の判定には総合臨床重症度スコア を用いる。40 点 を超える例では集学的治療会議 を推奨する (架空)。","recommended_action":"重症度分類は腫瘍組織機能重症度分類 (架空)に準拠し、**5 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"},{"label":"クオル","criteria":"腫瘍性疾患重症度分類 (架空) による評価で高度腫瘍組織障害域 以上に該当する場合は、入院加療を考慮する。 (架空)","recommended_action":"重症度分類は腫瘍組織機能重症度分類 (架空)に準拠し、**5 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"}]},"differential_diagnoses":["オータブレ","ヤロオク","チルイン"],"complications":["ライニ","テイベル"],"treatments":{"pharmacological":[{"drug_category":"ヨイアリメ","drug_ids":[],"indication":"腫瘍性疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","notes":"腫瘍性疾患標準治療 を第一選択とする。効果不十分例では分子標的治療の検討を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"},{"drug_category":"クオンフガエル","drug_ids":[],"indication":"腫瘍性疾患標準治療 を第一選択とする。効果不十分例では分子標的治療の検討を追加し、改善が乏しい場合は腫瘍内科へ紹介する。 (架空)","notes":"急性期には腫瘍量評価と支持療法を実施し、安定期へ移行後は寛解維持療法による維持療法を継続する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["プリスザンフェッスイオン","フェイジエル"],"description":"腫瘍性疾患管理 を第一選択とする。効果不十分例では分子標的治療の検討を追加し、改善が乏しい場合は腫瘍内科へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には腫瘍性疾患急性期プロトコルを実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"腫瘍性疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は腫瘍内科へ紹介する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"未治療例では臓器浸潤を合併する例が散見されるため、定期的な画像検査 による経過観察が重要である。 (架空)","prevention":["禁煙支援","禁煙支援"],"related_drug_ids":["drug_0081"],"related_disease_ids":["disease_0051"],"revised_at":"2026-04-16","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0008', $seed_json$
{"id":"disease_0008","name":"ルモンドウンイ","name_kana":"ルモンドウンイ","name_english":"Rmon'Duny","icd10_chapter":"chapter_ii","medical_department":["internal_medicine","surgery"],"chronicity":"chronic","infectious":false,"synonyms":["タインマル"],"summary":"ルモンドウンイは、異常細胞増殖を特徴とする急性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":25.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 25 (架空)"},"onset_age_range":{"min_age_years":58,"max_age_years":67,"label":"58-67 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["喫煙歴","発癌物質曝露","慢性炎症"]},"etiology":"ルモンドウンイは、異常細胞増殖を特徴とする慢性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["食欲不振","疼痛","息切れ","発熱","食欲不振"],"associated_symptoms":["発汗","悪心"],"onset_pattern":"subacute"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 病理組織検査の主要異常\n- 補助項目: 腫瘍性疾患評価スコアの上昇\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 腫瘤形成を示す中核所見\n- 補助項目: 腫瘍性疾患評価スコアの上昇\n(架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 腫瘍性疾患に特徴的な検査異常\n- 補助項目: 腫瘍マーカー検査の補助所見\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**病理組織検査の主要異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"腫瘍性疾患評価パネル による所見と腫瘤形成所見 の組み合わせで判定する。除外診断として腫瘍性疾患に類似する別疾患を除外することが必要。 (架空)"},"required_exams":[{"name":"心電図","category":"pathology","typical_finding":"クオヘイルドエン (架空)","reference_range":"アロオムレイ (架空)"},{"name":"血液生化学検査","category":"interview","typical_finding":"ボルオウル (架空)","reference_range":"スイネイ (架空)"},{"name":"MRI検査","category":"interview","typical_finding":"マクオ (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":{"grading_system":"ライオル","grades":[{"label":"クオル","criteria":"重症度分類は腫瘍性疾患重症度分類 (架空)に準拠し、**4 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"重症度の判定には腫瘍進展スコア を用いる。20 点 を超える例では入院管理の検討 を推奨する (架空)。"},{"label":"クアルムクオワルド","criteria":"重症度の判定には腫瘍組織機能スコア を用いる。50 点 を超える例では入院管理の検討 を推奨する (架空)。","recommended_action":"重症度の判定には腫瘍進展スコア を用いる。25 点 を超える例では集学的治療会議 を推奨する (架空)。"},{"label":"クアルムクオワルド","criteria":"重症度の判定には総合臨床重症度スコア を用いる。40 点 を超える例では専門チーム介入 を推奨する (架空)。","recommended_action":"重症度分類は腫瘍性疾患重症度分類 (架空)に準拠し、**5 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"}]},"differential_diagnoses":["ヒソンパヤ","リイツレ"],"complications":["ルクセイ","デスショウ","シヒ"],"treatments":{"pharmacological":[{"drug_category":"ショウェウレスイー","drug_ids":[],"indication":"腫瘍集学的治療 を第一選択とする。効果不十分例では分子標的治療の検討を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","notes":"標準治療は腫瘍性疾患標準治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から18 週間 後に効果判定を行う。 (架空)"},{"drug_category":"ハルクン","drug_ids":[],"indication":"腫瘍性疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","notes":"急性期には腫瘍量評価と支持療法を実施し、安定期へ移行後は腫瘍性疾患維持管理による維持療法を継続する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["フェイジエル","クトスレ"],"description":"急性期には腫瘍量評価と支持療法を実施し、安定期へ移行後は腫瘍性疾患維持管理による維持療法を継続する。 (架空)"},{"heading":"運動療法","items":["ベルウ","アンクリットレ"],"description":"腫瘍性疾患標準治療 を第一選択とする。効果不十分例では分子標的治療の検討を追加し、改善が乏しい場合は腫瘍内科へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"腫瘍性疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は腫瘍内科へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では腫瘍組織機能不全を合併する例が散見されるため、定期的な腫瘍性疾患定期評価 による経過観察が重要である。 (架空)","prevention":["家族歴に応じた相談"],"related_drug_ids":["drug_0080","drug_0082"],"related_disease_ids":["disease_0066","disease_0044"],"revised_at":"2026-04-15","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
