INSERT INTO diseases(public_id, data) VALUES ('disease_0010', $seed_json$
{"id":"disease_0010","name":"フレイブ","name_kana":"フレイブ","name_english":"Frey'Bu","icd10_chapter":"chapter_ii","medical_department":["internal_medicine","orthopedics"],"chronicity":"chronic","infectious":false,"synonyms":["エイツォ","ヤンクヘ","グライフ"],"summary":"フレイブは腫瘍性疾患に分類される疾患群で、クレアラッスを主訴に受診する例が多い。確定診断には**病理組織検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":40.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 40 (架空)"},"onset_age_range":{"min_age_years":35,"max_age_years":45,"label":"35-45 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["放射線曝露","放射線曝露"]},"etiology":"フレイブは造血器系に発現する病態で、緩徐発症の経過を呈する。推定有病率は人口 10 万対 24 (架空)。","symptoms":{"main_symptoms":["頭痛","体重減少","動悸","倦怠感","頭痛"],"associated_symptoms":["下痢","発汗","浮腫"],"onset_pattern":"intermittent"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 腫瘤形成を示す中核所見\n- 補助項目: 腫瘍性疾患評価スコアの上昇\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**腫瘤形成を示す中核所見** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 腫瘤形成を示す中核所見\n- 補助項目: 腫瘍マーカー検査の補助所見\n(架空)"],"supporting":["病理組織検査 による所見と腫瘤形成所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**腫瘤形成を示す中核所見** を満たし、かつ5 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"単純X線撮影","category":"pathology","typical_finding":"ボルオウル (架空)","reference_range":"ショウチョン (架空)"},{"name":"血液生化学検査","category":"interview","typical_finding":"ワア (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":{"grading_system":"イエヴィルニ","grades":[{"label":"クアルムクオワルド","criteria":"重症度の判定には腫瘍進展スコア を用いる。45 点 を超える例では入院管理の検討 を推奨する (架空)。","recommended_action":"腫瘍組織機能重症度分類 (架空) による評価で緊急介入域 以上に該当する場合は、入院加療を考慮する。 (架空)"},{"label":"アマン","criteria":"重症度分類は腫瘍組織機能重症度分類 (架空)に準拠し、**5 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"腫瘍性疾患重症度分類 (架空) による評価で高度腫瘍組織障害域 以上に該当する場合は、入院加療を考慮する。 (架空)"}]},"differential_diagnoses":["リットブグ","テルチ"],"complications":["シロ","ダピュセン"],"treatments":{"pharmacological":[{"drug_category":"クルクオン","drug_ids":[],"indication":"急性期には腫瘍量評価と支持療法を実施し、安定期へ移行後は腫瘍性疾患維持管理による維持療法を継続する。 (架空)","notes":"急性期には腫瘍性疾患急性期プロトコルを実施し、安定期へ移行後は腫瘍性疾患維持管理による維持療法を継続する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["クトスレ","フェイジエル"],"description":"急性期には腫瘍性疾患急性期プロトコルを実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は腫瘍性疾患維持管理による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"腫瘍性疾患標準治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は腫瘍内科へ紹介する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の腫瘍性疾患再燃率 は**約 70.0%** と報告される (架空)。","prevention":["飲酒量の調整","定期がん検診"],"related_drug_ids":["drug_0081"],"related_disease_ids":["disease_0067"],"revised_at":"2026-04-13","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0011', $seed_json$
{"id":"disease_0011","name":"タリパド","name_kana":"タリパド","name_english":"Tarip'ad","icd10_chapter":"chapter_ii","medical_department":["internal_medicine","neurology"],"chronicity":"chronic","infectious":false,"synonyms":["ツイル"],"summary":"タリパドは、腫瘤形成を特徴とする急性疾患である。成人に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":41.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 41 (架空)"},"onset_age_range":{"min_age_years":20,"max_age_years":31,"label":"20-31 代"},"sex_ratio":{"male_ratio":1,"female_ratio":1,"note":"架空比率"},"risk_factors":["発癌物質曝露","慢性炎症","発癌物質曝露"]},"etiology":"タリパドは、異常細胞増殖を特徴とする慢性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["発熱","息切れ","疼痛","食欲不振","発熱"],"associated_symptoms":["悪心","めまい"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**腫瘍性疾患に特徴的な検査異常** を満たし、かつ5 項目以上を充足する場合に確定診断とする。 (架空)","腫瘍性疾患評価パネル による所見と腫瘤形成所見 の組み合わせで判定する。除外診断として腫瘍性疾患に類似する別疾患を除外することが必要。 (架空)"],"supporting":["病理組織検査 による所見と腫瘤形成所見 の組み合わせで判定する。除外診断として腫瘍性疾患に類似する別疾患を除外することが必要。 (架空)","病理組織検査 による所見と腫瘤形成所見 の組み合わせで判定する。除外診断として腫瘍性疾患に類似する別疾患を除外することが必要。 (架空)"],"notes":"腫瘍性疾患評価パネル による所見と腫瘍組織機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"},"required_exams":[{"name":"心電図","category":"pathology","typical_finding":"クオヘイルドエン (架空)","reference_range":"アロオムレイ (架空)"},{"name":"CT検査","category":"physiological","typical_finding":"モクオン (架空)","reference_range":"ショウチョン (架空)"},{"name":"問診票","category":"interview","typical_finding":"クオヘイルドエン (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":{"grading_system":"クレアラフォシ","grades":[{"label":"ムクプゼルウ","criteria":"腫瘍性疾患重症度分類 (架空) による評価で腫瘍性疾患重症域 以上に該当する場合は、入院加療を考慮する。 (架空)","recommended_action":"重症度の判定には総合臨床重症度スコア を用いる。65 点 を超える例では入院管理の検討 を推奨する (架空)。"},{"label":"ヒクス","criteria":"重症度の判定には腫瘍組織機能スコア を用いる。45 点 を超える例では入院管理の検討 を推奨する (架空)。","recommended_action":"重症度の判定には腫瘍組織機能スコア を用いる。65 点 を超える例では専門チーム介入 を推奨する (架空)。"},{"label":"クアルムクオワルド","criteria":"腫瘍組織機能重症度分類 (架空) による評価で高度腫瘍組織障害域 以上に該当する場合は、入院加療を考慮する。 (架空)","recommended_action":"重症度の判定には腫瘍進展スコア を用いる。35 点 を超える例では集学的治療会議 を推奨する (架空)。"}]},"differential_diagnoses":["ワチウィ","サイ"],"complications":["ダウイル","イルモリ"],"treatments":{"pharmacological":[{"drug_category":"ヨンラズイ","drug_ids":[],"indication":"標準治療は腫瘍性疾患標準治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から6 週間 後に効果判定を行う。 (架空)","notes":"急性期には腫瘍量評価と支持療法を実施し、安定期へ移行後は寛解維持療法による維持療法を継続する。 (架空)"},{"drug_category":"ヨイアリメ","drug_ids":[],"indication":"標準治療は腫瘍性疾患管理を中心とし、症状に応じて緩和ケア支援を併用する。治療開始から16 週間 後に効果判定を行う。 (架空)","notes":"標準治療は腫瘍性疾患標準治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から2 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ベルウ","アンクリットレ"],"description":"腫瘍性疾患標準治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"},{"heading":"運動療法","items":["フェイジエル","プリスザンフェッスイオン"],"description":"腫瘍集学的治療 を第一選択とする。効果不十分例では分子標的治療の検討を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は腫瘍性疾患管理を中心とし、症状に応じて緩和ケア支援を併用する。治療開始から6 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"本疾患の予後は腫瘍性疾患の初期重症度 に大きく左右される。**早期診断** を満たす症例では再燃リスクの低下 が期待できる。 (架空)","prevention":["家族歴に応じた相談"],"related_drug_ids":["drug_0082","drug_0080"],"related_disease_ids":["disease_0048","disease_0078"],"revised_at":"2026-04-12","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
