INSERT INTO diseases(public_id, data) VALUES ('disease_0012', $seed_json$
{"id":"disease_0012","name":"フレイクオ","name_kana":"フレイクオ","name_english":"Frey'Co","icd10_chapter":"chapter_iii","medical_department":["internal_medicine","pediatrics"],"chronicity":"subacute","infectious":false,"synonyms":["リタヴェン","ビスリケス"],"summary":"フレイクオは血液免疫疾患に分類される疾患群で、イルラクを主訴に受診する例が多い。確定診断には**凝固機能検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":24.0,"denominator":100,"unit":"per_patient","label":"患者 100 対 24 (架空)"},"onset_age_range":{"min_age_years":32,"max_age_years":52,"label":"32-52 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["慢性出血","抗凝固薬使用"]},"etiology":"フレイクオは、凝固能の異常を特徴とする亜急性疾患である。成人に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["倦怠感","動悸","体重減少","頭痛","倦怠感"],"associated_symptoms":["便秘","下痢","不眠"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 血球異常を示す中核所見\n- 補助項目: 血液免疫疾患評価スコアの上昇\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**血算検査の主要異常** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)","血液免疫疾患評価パネル による所見と血液免疫疾患に整合する身体所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 血球異常を示す中核所見\n- 補助項目: 血液関連指標の軽度異常\n(架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**血液免疫疾患に特徴的な検査異常** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"内視鏡検査","category":"blood_test","typical_finding":"モクオン (架空)","reference_range":"スイネイ (架空)"},{"name":"単純X線撮影","category":"pathology","typical_finding":"マクオ (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["ヨンジャ","ベゴ","ジオド"],"complications":["クレアラトレンチャ","ヤノ","ジオヒソン"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","イクルエ"],"description":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"血液免疫疾患管理 を第一選択とする。効果不十分例では免疫調整療法を追加し、改善が乏しい場合は血液内科へ紹介する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"血液免疫疾患標準治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の血液指標安定率 は**約 66.5%** と報告される (架空)。","prevention":["栄養状態の評価","定期血液検査"],"related_drug_ids":["drug_0025"],"related_disease_ids":["disease_0057"],"revised_at":"2026-04-11","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
