INSERT INTO diseases(public_id, data) VALUES ('disease_0013', $seed_json$
{"id":"disease_0013","name":"ラトレンチャ","name_kana":"ラトレンチャ","name_english":"Ra'Trench","icd10_chapter":"chapter_iii","medical_department":["internal_medicine","otolaryngology"],"chronicity":"subacute","infectious":false,"synonyms":["ベウルル","テルク","ウワルド"],"summary":"ラトレンチャは凝固異常疾患に分類される疾患群で、シアルを主訴に受診する例が多い。確定診断には**血算検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":39.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 39 (架空)"},"onset_age_range":{"min_age_years":52,"max_age_years":65,"label":"52-65 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["鉄欠乏","栄養障害","栄養障害"]},"etiology":"ラトレンチャは骨髄系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 9 (架空)。","symptoms":{"main_symptoms":["息切れ","発熱","食欲不振","疼痛","息切れ"],"associated_symptoms":["浮腫","不眠"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 血算検査の主要異常\n- 補助項目: 血液免疫疾患評価スコアの上昇\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**血液免疫疾患に特徴的な検査異常** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["本基準は架空値であり、実臨床の診断には使用しない。**血液免疫疾患に特徴的な検査異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)","血液免疫疾患評価パネル による所見と血液免疫疾患に整合する身体所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 血液免疫疾患に特徴的な検査異常\n- 補助項目: 血液免疫疾患評価スコアの上昇\n(架空)"},"required_exams":[{"name":"血液生化学検査","category":"blood_test","typical_finding":"クオヘイルドエン (架空)","reference_range":"アロオムレイ (架空)"},{"name":"CT検査","category":"physiological","typical_finding":"ボルオウル (架空)","reference_range":"スイネイ (架空)"},{"name":"心電図","category":"interview","typical_finding":"クオヘイルドエン (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["オセエクイ"],"complications":["テイッド","デスウ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ラウセオテ","ワチウェ"],"description":"標準治療は血液免疫疾患標準治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から12 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["ジオエナ","ワチウェ"],"description":"血液免疫疾患標準治療 を第一選択とする。効果不十分例では免疫調整療法を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"血液免疫疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では血液機能不全を合併する例が散見されるため、定期的な血算検査 による経過観察が重要である。 (架空)","prevention":["鉄摂取の最適化"],"related_drug_ids":["drug_0082","drug_0022"],"related_disease_ids":["disease_0078","disease_0000"],"revised_at":"2026-04-10","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
