INSERT INTO diseases(public_id, data) VALUES ('disease_0014', $seed_json$
{"id":"disease_0014","name":"クトゥル","name_kana":"クトゥル","name_english":"k'Tur","icd10_chapter":"chapter_iii","medical_department":["internal_medicine","urology"],"chronicity":"subacute","infectious":false,"synonyms":["リオン","チルクア","エイデニョウ"],"summary":"クトゥルは血液系に発現する病態で、急性発症の経過を呈する。推定有病率は人口 10 万対 27 (架空)。","epidemiology":{"prevalence":{"rate":32.0,"denominator":100,"unit":"per_patient","label":"患者 100 対 32 (架空)"},"onset_age_range":{"min_age_years":43,"max_age_years":57,"label":"43-57 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["骨髄抑制","骨髄抑制"]},"etiology":"クトゥルは造血機能疾患に分類される疾患群で、リングアククを主訴に受診する例が多い。確定診断には**血液免疫疾患評価パネル** を用いる。 (架空)","symptoms":{"main_symptoms":["動悸","倦怠感","頭痛","体重減少","動悸"],"associated_symptoms":["便秘","悪心","便秘"],"onset_pattern":"intermittent"},"diagnostic_criteria":{"required":["凝固機能検査 による所見と血液機能の変化 の組み合わせで判定する。除外診断として二次性血液異常を除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 血球異常を示す中核所見\n- 補助項目: 凝固機能検査の補助所見\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 血球異常を示す中核所見\n- 補助項目: 凝固機能検査の補助所見\n(架空)"],"supporting":["血液免疫疾患評価パネル による所見と血液免疫疾患に整合する身体所見 の組み合わせで判定する。除外診断として血液免疫疾患に類似する別疾患を除外することが必要。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**血球異常を示す中核所見** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"血液生化学検査","category":"blood_test","typical_finding":"ボルオウル (架空)","reference_range":"ロジアル (架空)"},{"name":"CT検査","category":"blood_test","typical_finding":"ワア (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["ルチライ","ヤニグ","ツパイ"],"complications":["リングモレ","テイオレ","ドンイフレイ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","イクルエ"],"description":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は血液免疫疾患維持管理による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は血液免疫疾患維持管理による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"急性期には血液免疫疾患急性期プロトコルを実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"本疾患の予後は治療開始までの期間 に大きく左右される。**早期診断** を満たす症例では出血予防 が期待できる。 (架空)","prevention":["定期血液検査","栄養状態の評価"],"related_drug_ids":["drug_0025"],"related_disease_ids":["disease_0063"],"revised_at":"2026-04-09","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0015', $seed_json$
{"id":"disease_0015","name":"ルモンラン","name_kana":"ルモンラン","name_english":"Rmon'Lan","icd10_chapter":"chapter_iv","medical_department":["endocrinology","dermatology"],"chronicity":"chronic","infectious":false,"synonyms":["オヒヌ","ヤリグ","ライファイ"],"summary":"ルモンランは、代謝恒常性の破綻を特徴とする亜急性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":31.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 31 (架空)"},"onset_age_range":{"min_age_years":42,"max_age_years":57,"label":"42-57 代"},"sex_ratio":{"male_ratio":1,"female_ratio":1,"note":"架空比率"},"risk_factors":["肥満","ステロイド使用","ステロイド使用"]},"etiology":"ルモンランは、代謝恒常性の破綻を特徴とする慢性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["疼痛","食欲不振","発熱","息切れ"],"associated_symptoms":["悪心","浮腫"],"onset_pattern":"subacute"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**内分泌負荷検査の主要異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)","内分泌負荷検査 による所見と代謝調節機能の変化 の組み合わせで判定する。除外診断として内分泌代謝疾患に類似する別疾患を除外することが必要。 (架空)"],"supporting":["本基準は架空値であり、実臨床の診断には使用しない。**ホルモン異常を示す中核所見** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)","代謝指標検査 による所見と代謝調節機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"notes":"内分泌代謝疾患評価パネル による所見と代謝調節機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"},"required_exams":[{"name":"内視鏡検査","category":"blood_test","typical_finding":"ワア (架空)","reference_range":"クンレカ (架空)"},{"name":"CT検査","category":"imaging","typical_finding":"ボルオウル (架空)","reference_range":"スイネイ (架空)"},{"name":"内視鏡検査","category":"physiological","typical_finding":"ワア (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["マイリル","アイギエ"],"complications":["ヤデミク","テイケク"],"treatments":{"pharmacological":[{"drug_category":"ヒロマイ","drug_ids":[],"indication":"内分泌代謝疾患標準治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","notes":"内分泌代謝疾患標準治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は内分泌代謝内科へ紹介する。 (架空)"},{"drug_category":"ウンドソエ","drug_ids":[],"indication":"標準治療は代謝管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から8 週間 後に効果判定を行う。 (架空)","notes":"代謝管理 を第一選択とする。効果不十分例では専門薬物療法を追加し、改善が乏しい場合は内分泌代謝内科へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ラウセオテ","ワチテル"],"description":"標準治療は内分泌代謝疾患標準治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から14 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["ラウセオテ","ワチウェ"],"description":"標準治療は内分泌代謝疾患標準治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から14 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"内分泌代謝疾患管理 を第一選択とする。効果不十分例では専門薬物療法を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の内分泌代謝疾患再燃率 は**約 70.0%** と報告される (架空)。","prevention":["血糖確認"],"related_drug_ids":["drug_0014","drug_0000"],"related_disease_ids":["disease_0028","disease_0002"],"revised_at":"2026-04-08","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
