INSERT INTO diseases(public_id, data) VALUES ('disease_0018', $seed_json$
{"id":"disease_0018","name":"シャユ","name_kana":"シャユ","name_english":"Sha'yu","icd10_chapter":"chapter_iv","medical_department":["endocrinology","infectious_disease"],"chronicity":"chronic","infectious":false,"synonyms":["ジオアン","マイラウ"],"summary":"シャユは、栄養利用の変化を特徴とする亜急性疾患である。成人に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":24.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 24 (架空)"},"onset_age_range":{"min_age_years":29,"max_age_years":47,"label":"29-47 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["運動不足","内分泌素因"]},"etiology":"シャユは内分泌系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 14 (架空)。","symptoms":{"main_symptoms":["頭痛","体重減少","動悸","倦怠感","頭痛"],"associated_symptoms":["不眠","悪心","浮腫"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["内分泌負荷検査 による所見と内分泌代謝疾患に整合する身体所見 の組み合わせで判定する。除外診断として薬剤性代謝異常を除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 内分泌負荷検査の主要異常\n- 補助項目: 代謝調節関連指標の軽度異常\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**内分泌代謝疾患に特徴的な検査異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: ホルモン異常を示す中核所見\n- 補助項目: 内分泌代謝疾患評価スコアの上昇\n(架空)"],"notes":"内分泌代謝疾患評価パネル による所見と内分泌代謝疾患に整合する身体所見 の組み合わせで判定する。除外診断として内分泌代謝疾患に類似する別疾患を除外することが必要。 (架空)"},"required_exams":[{"name":"心電図","category":"blood_test","typical_finding":"ヒロト (架空)","reference_range":"スイネイ (架空)"},{"name":"MRI検査","category":"interview","typical_finding":"ワア (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["ジオオンド"],"complications":["ダドグ","トゲドル","ジオバットエ"],"treatments":{"pharmacological":[{"drug_category":"ウンドソエ","drug_ids":[],"indication":"急性期には代謝異常の是正を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)","notes":"内分泌代謝疾患標準治療 を第一選択とする。効果不十分例では専門薬物療法を追加し、改善が乏しい場合は内分泌代謝内科へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ワチウェ","イクルエ"],"description":"急性期には代謝異常の是正を実施し、安定期へ移行後はホルモン補正療法による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には内分泌代謝疾患急性期プロトコルを実施し、安定期へ移行後は内分泌代謝疾患維持管理による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"標準治療は内分泌代謝疾患管理を中心とし、症状に応じて生活機能支援を併用する。治療開始から8 週間 後に効果判定を行う。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"未治療例では代謝調節機能不全を合併する例が散見されるため、定期的な代謝指標検査 による経過観察が重要である。 (架空)","prevention":["食事内容の調整","食事内容の調整"],"related_drug_ids":["drug_0017"],"related_disease_ids":["disease_0075"],"revised_at":"2026-04-05","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0019', $seed_json$
{"id":"disease_0019","name":"モンクエル","name_kana":"モンクエル","name_english":"mon'ker","icd10_chapter":"chapter_iv","medical_department":["endocrinology","gynecology"],"chronicity":"chronic","infectious":false,"synonyms":["ジェエングイエ","ムベ","スエイト"],"summary":"モンクエルは内分泌系に発現する病態で、急性発症の経過を呈する。推定有病率は人口 10 万対 17 (架空)。","epidemiology":{"prevalence":{"rate":7.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 7 (架空)"},"onset_age_range":{"min_age_years":25,"max_age_years":44,"label":"25-44 代"},"sex_ratio":{"male_ratio":1,"female_ratio":1,"note":"架空比率"},"risk_factors":["ステロイド使用","ステロイド使用","肥満"]},"etiology":"モンクエルは栄養代謝疾患に分類される疾患群で、ヤクウを主訴に受診する例が多い。確定診断には**内分泌負荷検査** を用いる。 (架空)","symptoms":{"main_symptoms":["発熱","息切れ","疼痛","食欲不振"],"associated_symptoms":["下痢","下痢"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["内分泌負荷検査 による所見と代謝調節機能の変化 の組み合わせで判定する。除外診断として内分泌代謝疾患に類似する別疾患を除外することが必要。 (架空)","内分泌負荷検査 による所見と代謝調節機能の変化 の組み合わせで判定する。除外診断として内分泌代謝疾患に類似する別疾患を除外することが必要。 (架空)"],"supporting":["内分泌負荷検査 による所見と内分泌代謝疾患に整合する身体所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 内分泌代謝疾患に特徴的な検査異常\n- 補助項目: 代謝調節関連指標の軽度異常\n(架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 内分泌負荷検査の主要異常\n- 補助項目: 代謝指標検査の補助所見\n(架空)"},"required_exams":[{"name":"心電図","category":"blood_test","typical_finding":"マクオ (架空)","reference_range":"アロオムレイ (架空)"},{"name":"問診票","category":"pathology","typical_finding":"ボルオウル (架空)","reference_range":"ロジアル (架空)"},{"name":"単純X線撮影","category":"physiological","typical_finding":"クオヘイルドエン (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["プリッスイリ"],"complications":["ライククウルレ","ヤリエ","テイオト"],"treatments":{"pharmacological":[{"drug_category":"エイフマジェ","drug_ids":[],"indication":"標準治療は内分泌代謝疾患標準治療を中心とし、症状に応じて食事運動支援を併用する。治療開始から14 週間 後に効果判定を行う。 (架空)","notes":"急性期には代謝異常の是正を実施し、安定期へ移行後は内分泌代謝疾患維持管理による維持療法を継続する。 (架空)"},{"drug_category":"ガエルルドオン","drug_ids":[],"indication":"標準治療は内分泌代謝疾患管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から4 週間 後に効果判定を行う。 (架空)","notes":"標準治療は内分泌代謝疾患管理を中心とし、症状に応じて生活機能支援を併用する。治療開始から16 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["イクルエ","ワチウェ"],"description":"標準治療は代謝管理を中心とし、症状に応じて生活機能支援を併用する。治療開始から10 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["ジオエナ","ウセ"],"description":"内分泌代謝疾患管理 を第一選択とする。効果不十分例では専門薬物療法を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"内分泌代謝疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では代謝調節機能不全を合併する例が散見されるため、定期的な代謝指標検査 による経過観察が重要である。 (架空)","prevention":["血糖確認"],"related_drug_ids":["drug_0018","drug_0012"],"related_disease_ids":["disease_0008","disease_0006"],"revised_at":"2026-04-04","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
