INSERT INTO diseases(public_id, data) VALUES ('disease_0022', $seed_json$
{"id":"disease_0022","name":"不眠症","name_kana":"フミンショウ","name_english":"Insomnia (fictional)","icd10_chapter":"chapter_v","medical_department":["psychiatry","gastroenterology"],"chronicity":"chronic","infectious":false,"synonyms":["睡眠障害（不眠型）","インソムニア"],"summary":"入眠困難、中途覚醒、早朝覚醒又は睡眠の質低下が持続し、日中機能障害を伴う睡眠障害 (架空)","epidemiology":{"prevalence":{"rate":31.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 31 (架空)"},"onset_age_range":{"min_age_years":26,"max_age_years":31,"label":"26-31 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["物質使用","心理社会的ストレス","物質使用"]},"etiology":"心理的要因、ストレス、生活習慣、身体疾患及び睡眠環境の乱れが複合して発症する (架空)","symptoms":{"main_symptoms":["入眠困難 (架空)","中途覚醒 (架空)","早朝覚醒 (架空)","睡眠の質低下による日中機能障害 (架空)"],"associated_symptoms":["日中の眠気 (架空)","集中力低下 (架空)","易刺激性 (架空)"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["入眠困難、中途覚醒又は早朝覚醒が週 3 晩以上みられる (架空)","症状が 3 ヶ月以上持続し日中機能障害を伴う (架空)"],"supporting":["睡眠機会が十分にあるにもかかわらず睡眠困難が持続する (架空)","薬物、身体疾患又は他の睡眠障害だけでは説明できない (架空)"],"notes":"DSM-5 及び ICD-10 の不眠症診断基準を参考にした架空 fixture である (架空)"},"required_exams":[{"name":"睡眠歴問診","category":"interview","typical_finding":"睡眠時間、入眠潜時、中途覚醒及び日中機能障害を聴取する (架空)","reference_range":null},{"name":"睡眠質問票","category":"interview","typical_finding":"睡眠の質低下と生活への支障を評価する (架空)","reference_range":"支障なし (架空)"},{"name":"睡眠日誌","category":"physiological","typical_finding":"就床時刻、覚醒回数、睡眠効率の低下を確認する (架空)","reference_range":null}],"severity_grading":null,"differential_diagnoses":["睡眠時無呼吸症候群 (架空)","むずむず脚症候群 (架空)","うつ病 (架空)"],"complications":["日中の認知機能低下 (架空)","事故リスク増大 (架空)","心血管疾患リスク増大 (架空)"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"睡眠衛生指導","items":["就床時刻の固定 (架空)","カフェイン摂取制限 (架空)","寝室環境の調整 (架空)"],"description":"睡眠を妨げる生活習慣と環境要因を整える (架空)"},{"heading":"認知行動療法","items":["刺激制御法 (架空)","睡眠制限法 (架空)","認知再構成 (架空)"],"description":"不眠を維持する認知と行動パターンを修正する (架空)"},{"heading":"環境調整","items":["光環境調整 (架空)","騒音対策 (架空)","就寝前スクリーン制限 (架空)"],"description":"睡眠の質を妨げる外的刺激を減らす (架空)"}],"acute_phase_protocol":[]},"prognosis":"適切な睡眠衛生指導と認知行動療法で改善が見込まれるが、長期化すると慢性化する (架空)","prevention":["規則的な睡眠覚醒リズムの維持 (架空)","就寝前の刺激物と強い光の回避 (架空)","ストレス管理と適度な運動 (架空)"],"related_drug_ids":["drug_0089"],"related_disease_ids":["disease_0023","disease_0008"],"revised_at":"2026-04-01","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
