INSERT INTO diseases(public_id, data) VALUES ('disease_0023', $seed_json$
{"id":"disease_0023","name":"ムロ","name_kana":"ムロ","name_english":"mu'Ro","icd10_chapter":"chapter_v","medical_department":["psychiatry"],"chronicity":"chronic","infectious":false,"synonyms":["リイタイク"],"summary":"ムロは精神機能系に発現する病態で、急性発症の経過を呈する。推定有病率は人口 10 万対 28 (架空)。","epidemiology":{"prevalence":{"rate":24.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 24 (架空)"},"onset_age_range":{"min_age_years":49,"max_age_years":61,"label":"49-61 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["家族歴","睡眠不足"]},"etiology":"ムロは、情動調節の変化を特徴とする急性疾患である。成人に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["倦怠感","動悸","体重減少"],"associated_symptoms":["めまい","発汗","発汗"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 精神行動疾患に特徴的な検査異常\n- 補助項目: 心理評価尺度の補助所見\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**精神行動疾患に特徴的な検査異常** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)","精神行動疾患評価パネル による所見と認知情動機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"supporting":["精神行動疾患評価パネル による所見と認知情動機能の変化 の組み合わせで判定する。除外診断として神経疾患に伴う行動変化を除外することが必要。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**行動変化を示す中核所見** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"単純X線撮影","category":"interview","typical_finding":"ボルオウル (架空)","reference_range":"ショウチョン (架空)"},{"name":"心電図","category":"physiological","typical_finding":"ワア (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["ライネイ"],"complications":["クレアラレイ","リングティオン"],"treatments":{"pharmacological":[{"drug_category":"ゲドイザ","drug_ids":[],"indication":"標準治療は精神行動疾患管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から10 週間 後に効果判定を行う。 (架空)","notes":"急性期には危機介入を実施し、安定期へ移行後は精神行動疾患維持管理による維持療法を継続する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ライメイ","マイワチ"],"description":"標準治療は心理社会的治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から14 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は精神行動疾患標準治療を中心とし、症状に応じて家族支援を併用する。治療開始から14 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"標準治療は精神行動疾患管理を中心とし、症状に応じて家族支援を併用する。治療開始から2 週間 後に効果判定を行う。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の精神行動疾患再燃率 は**約 82.0%** と報告される (架空)。","prevention":["睡眠リズムの維持","睡眠リズムの維持"],"related_drug_ids":["drug_0089","drug_0088"],"related_disease_ids":["disease_0017"],"revised_at":"2026-03-31","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
