INSERT INTO diseases(public_id, data) VALUES ('disease_0025', $seed_json$
{"id":"disease_0025","name":"ルモンレエ","name_kana":"ルモンレエ","name_english":"Rmon'lee","icd10_chapter":"chapter_v","medical_department":["psychiatry","endocrinology"],"chronicity":"chronic","infectious":false,"synonyms":["ジオグライ"],"summary":"ルモンレエは、情動調節の変化を特徴とする亜急性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":24.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 24 (架空)"},"onset_age_range":{"min_age_years":41,"max_age_years":47,"label":"41-47 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["睡眠不足","発達特性"]},"etiology":"ルモンレエは精神行動疾患に分類される疾患群で、ヤメイを主訴に受診する例が多い。確定診断には**心理評価尺度** を用いる。 (架空)","symptoms":{"main_symptoms":["動悸","倦怠感","頭痛"],"associated_symptoms":["めまい","不眠","発汗"],"onset_pattern":"intermittent"},"diagnostic_criteria":{"required":["構造化面接 による所見と行動変化所見 の組み合わせで判定する。除外診断として精神行動疾患に類似する別疾患を除外することが必要。 (架空)","精神行動疾患評価パネル による所見と精神行動疾患に整合する身体所見 の組み合わせで判定する。除外診断として精神行動疾患に類似する別疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**精神行動疾患に特徴的な検査異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 行動変化を示す中核所見\n- 補助項目: 認知情動関連指標の軽度異常\n(架空)"],"notes":"心理評価尺度 による所見と認知情動機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"},"required_exams":[{"name":"MRI検査","category":"interview","typical_finding":"ヒロト (架空)","reference_range":"ショウチョン (架空)"},{"name":"内視鏡検査","category":"pathology","typical_finding":"クオヘイルドエン (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["スブ"],"complications":["デスクラクイ","デスアト","シルトンレ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["フレイェン","マイワチ"],"description":"急性期には精神行動疾患急性期プロトコルを実施し、安定期へ移行後は心理教育と服薬支援による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は精神行動疾患管理を中心とし、症状に応じて家族支援を併用する。治療開始から2 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"精神行動疾患管理 を第一選択とする。効果不十分例では専門精神療法を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の症状安定率 は**約 86.5%** と報告される (架空)。","prevention":["睡眠リズムの維持","ストレス対処"],"related_drug_ids":["drug_0089","drug_0088"],"related_disease_ids":["disease_0071"],"revised_at":"2026-03-29","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
