INSERT INTO diseases(public_id, data) VALUES ('disease_0026', $seed_json$
{"id":"disease_0026","name":"ヒソンフ","name_kana":"ヒソンフ","name_english":"hison'Fu","icd10_chapter":"chapter_v","medical_department":["psychiatry","surgery"],"chronicity":"chronic","infectious":false,"synonyms":["ラメプ","セモト"],"summary":"ヒソンフは精神機能系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 42 (架空)。","epidemiology":{"prevalence":{"rate":13.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 13 (架空)"},"onset_age_range":{"min_age_years":60,"max_age_years":69,"label":"60-69 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["物質使用","孤立","心理社会的ストレス"]},"etiology":"ヒソンフは、情動調節の変化を特徴とする急性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["食欲不振","疼痛","息切れ"],"associated_symptoms":["便秘","下痢"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["精神行動疾患評価パネル による所見と行動変化所見 の組み合わせで判定する。除外診断として精神行動疾患に類似する別疾患を除外することが必要。 (架空)","心理評価尺度 による所見と行動変化所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"supporting":["精神行動疾患評価パネル による所見と精神行動疾患に整合する身体所見 の組み合わせで判定する。除外診断として神経疾患に伴う行動変化を除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 行動変化を示す中核所見\n- 補助項目: 心理評価尺度の補助所見\n(架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**構造化面接の主要異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"CT検査","category":"interview","typical_finding":"クオヘイルドエン (架空)","reference_range":"オグンレイ (架空)"},{"name":"MRI検査","category":"pathology","typical_finding":"モクオン (架空)","reference_range":"ショウチョン (架空)"},{"name":"血液生化学検査","category":"blood_test","typical_finding":"クオヘイルドエン (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["ベオト"],"complications":["ルクウ","イルトゥニ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["エイデンル","フレイェン"],"description":"急性期には危機介入を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)"},{"heading":"運動療法","items":["エイデンル","フレイェン"],"description":"精神行動疾患標準治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は精神行動疾患管理を中心とし、症状に応じて生活機能支援を併用する。治療開始から16 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では社会機能低下を合併する例が散見されるため、定期的な心理評価尺度 による経過観察が重要である。 (架空)","prevention":["心理的支援"],"related_drug_ids":["drug_0089","drug_0097","drug_0087"],"related_disease_ids":["disease_0034","disease_0044"],"revised_at":"2026-03-28","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0027', $seed_json$
{"id":"disease_0027","name":"タインヌジトイ","name_kana":"タインヌジトイ","name_english":"Tain'Njity","icd10_chapter":"chapter_vi","medical_department":["neurology","ophthalmology"],"chronicity":"chronic","infectious":false,"synonyms":["ラメオンズ","ディヴィユ","クトオブ"],"summary":"タインヌジトイは神経疾患に分類される疾患群で、イルクラルイを主訴に受診する例が多い。確定診断には**神経画像検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":14.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 14 (架空)"},"onset_age_range":{"min_age_years":20,"max_age_years":36,"label":"20-36 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["糖代謝異常","家族歴"]},"etiology":"タインヌジトイは中枢神経疾患に分類される疾患群で、イルプを主訴に受診する例が多い。確定診断には**神経疾患評価パネル** を用いる。 (架空)","symptoms":{"main_symptoms":["体重減少","頭痛","倦怠感","動悸"],"associated_symptoms":["悪心","浮腫","発汗"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**神経画像検査の主要異常** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 神経脱落を示す中核所見\n- 補助項目: 神経関連指標の軽度異常\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 神経画像検査の主要異常\n- 補助項目: 神経生理検査の補助所見\n(架空)"],"supporting":["本基準は架空値であり、実臨床の診断には使用しない。**神経疾患に特徴的な検査異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**神経疾患に特徴的な検査異常** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"CT検査","category":"physiological","typical_finding":"ボルオウル (架空)","reference_range":"ロジアル (架空)"},{"name":"CT検査","category":"imaging","typical_finding":"ワア (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["モンスウ","ルジオジュンドイク","テルドクウン"],"complications":["ライラララ","ルクエクアン","ルクサ"],"treatments":{"pharmacological":[{"drug_category":"イェ","drug_ids":[],"indication":"神経機能管理 を第一選択とする。効果不十分例では神経専門薬の調整を追加し、改善が乏しい場合は神経内科へ紹介する。 (架空)","notes":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)"},{"drug_category":"エイフマジェ","drug_ids":[],"indication":"急性期には急性神経症状への対応を実施し、安定期へ移行後は神経リハビリ継続による維持療法を継続する。 (架空)","notes":"神経疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は神経内科へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","ラウセオテ"],"description":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は神経リハビリ継続による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は神経疾患標準治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から24 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"急性期には急性神経症状への対応を実施し、安定期へ移行後は神経リハビリ継続による維持療法を継続する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"未治療例では運動機能低下を合併する例が散見されるため、定期的な神経画像検査 による経過観察が重要である。 (架空)","prevention":["血圧管理","血圧管理"],"related_drug_ids":["drug_0098"],"related_disease_ids":["disease_0029"],"revised_at":"2026-03-27","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
