INSERT INTO diseases(public_id, data) VALUES ('disease_0030', $seed_json$
{"id":"disease_0030","name":"アンクデミク","name_kana":"アンクデミク","name_english":"Ank'Demic","icd10_chapter":"chapter_vi","medical_department":["neurology","psychiatry"],"chronicity":"chronic","infectious":false,"synonyms":["ドリグ","ルセナキュ"],"summary":"アンクデミクは、神経変性の進行を特徴とする慢性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":42.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 42 (架空)"},"onset_age_range":{"min_age_years":50,"max_age_years":62,"label":"50-62 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["家族歴","家族歴"]},"etiology":"アンクデミクは神経疾患に分類される疾患群で、トイムサクを主訴に受診する例が多い。確定診断には**神経画像検査** を用いる。 (架空)","symptoms":{"main_symptoms":["倦怠感","動悸","体重減少","頭痛"],"associated_symptoms":["不眠","発汗","発汗"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**神経画像検査の主要異常** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 神経疾患に特徴的な検査異常\n- 補助項目: 神経生理検査の補助所見\n(架空)","神経画像検査 による所見と神経機能の変化 の組み合わせで判定する。除外診断として神経疾患に類似する別疾患を除外することが必要。 (架空)"],"supporting":["本基準は架空値であり、実臨床の診断には使用しない。**神経画像検査の主要異常** を満たし、かつ5 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**神経画像検査の主要異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"内視鏡検査","category":"physiological","typical_finding":"ボルオウル (架空)","reference_range":"ショウチョン (架空)"},{"name":"問診票","category":"pathology","typical_finding":"クオヘイルドエン (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["アレトイ","ラハル"],"complications":["ダセン"],"treatments":{"pharmacological":[{"drug_category":"イェ","drug_ids":[],"indication":"標準治療は神経疾患管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から4 週間 後に効果判定を行う。 (架空)","notes":"標準治療は神経疾患管理を中心とし、症状に応じて生活機能支援を併用する。治療開始から18 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ウセ","ラウセオテ"],"description":"神経疾患標準治療 を第一選択とする。効果不十分例では神経専門薬の調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には急性神経症状への対応を実施し、安定期へ移行後は神経疾患維持管理による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"神経疾患管理 を第一選択とする。効果不十分例では神経専門薬の調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"本疾患の予後は神経疾患の初期重症度 に大きく左右される。**早期診断** を満たす症例では再燃リスクの低下 が期待できる。 (架空)","prevention":["睡眠評価","睡眠評価"],"related_drug_ids":["drug_0092"],"related_disease_ids":["disease_0017"],"revised_at":"2026-03-24","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0031', $seed_json$
{"id":"disease_0031","name":"ジャマ","name_kana":"ジャマ","name_english":"Ja'ma","icd10_chapter":"chapter_vii","medical_department":["ophthalmology","gastroenterology"],"chronicity":"acute","infectious":false,"synonyms":["ウシスレ","ビゴ","タリパロオム"],"summary":"ジャマは、視機能の低下を特徴とする慢性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":43.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 43 (架空)"},"onset_age_range":{"min_age_years":27,"max_age_years":32,"label":"27-32 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["眼圧上昇","眼外傷歴","加齢"]},"etiology":"ジャマは眼付属器疾患に分類される疾患群で、シサルを主訴に受診する例が多い。確定診断には**視野検査** を用いる。 (架空)","symptoms":{"main_symptoms":["息切れ","発熱","食欲不振","疼痛","息切れ"],"associated_symptoms":["めまい","浮腫"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 眼底検査の主要異常\n- 補助項目: 眼科疾患評価スコアの上昇\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**眼科疾患に特徴的な検査異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 眼底検査の主要異常\n- 補助項目: 視野検査の補助所見\n(架空)","眼科疾患評価パネル による所見と眼科疾患に整合する身体所見 の組み合わせで判定する。除外診断として眼科疾患に類似する別疾患を除外することが必要。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**視機能低下を示す中核所見** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"単純X線撮影","category":"physiological","typical_finding":"クオヘイルドエン (架空)","reference_range":"クンレカ (架空)"},{"name":"CT検査","category":"blood_test","typical_finding":"モクオン (架空)","reference_range":"ショウチョン (架空)"},{"name":"単純X線撮影","category":"pathology","typical_finding":"ワア (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["エイティル"],"complications":["ジオイツ","テイテイ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ラウセオテ","ワチテル"],"description":"標準治療は眼科治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から4 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["イクルエ","ワチウェ"],"description":"眼科疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"眼科疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は眼科へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"本疾患の予後は治療開始までの期間 に大きく左右される。**早期診断** を満たす症例では再燃リスクの低下 が期待できる。 (架空)","prevention":["糖代謝管理"],"related_drug_ids":["drug_0118"],"related_disease_ids":["disease_0022","disease_0040"],"revised_at":"2026-03-23","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
