INSERT INTO diseases(public_id, data) VALUES ('disease_0032', $seed_json$
{"id":"disease_0032","name":"チラド","name_kana":"チラド","name_english":"Chil'Ado","icd10_chapter":"chapter_viii","medical_department":["otolaryngology","infectious_disease"],"chronicity":"acute","infectious":false,"synonyms":["ククラルイ","シイアル","イショウレンクエ"],"summary":"チラドは聴覚器疾患に分類される疾患群で、ジオルクを主訴に受診する例が多い。確定診断には**聴力検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":30.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 30 (架空)"},"onset_age_range":{"min_age_years":56,"max_age_years":74,"label":"56-74 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["加齢","耳毒性薬剤使用"]},"etiology":"チラドは前庭機能疾患に分類される疾患群で、タンクエカアナサエルを主訴に受診する例が多い。確定診断には**前庭機能検査** を用いる。 (架空)","symptoms":{"main_symptoms":["頭痛","体重減少","動悸"],"associated_symptoms":["発汗","下痢","便秘"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**聴平衡機能低下を示す中核所見** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)","聴力検査 による所見と内耳機能の変化 の組み合わせで判定する。除外診断として耳鼻平衡疾患に類似する別疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**聴平衡機能低下を示す中核所見** を満たし、かつ5 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["耳鼻平衡疾患評価パネル による所見と耳鼻平衡疾患に整合する身体所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 聴力検査の主要異常\n- 補助項目: 耳鼻平衡疾患評価スコアの上昇\n(架空)"},"required_exams":[{"name":"内視鏡検査","category":"physiological","typical_finding":"ヒロト (架空)","reference_range":"ショウチョン (架空)"},{"name":"MRI検査","category":"imaging","typical_finding":"マクオ (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["テルミト","テルスオンド","オセルム"],"complications":["テイザ","トイムザンフェッスイオン"],"treatments":{"pharmacological":[{"drug_category":"ウンドソエ","drug_ids":[],"indication":"耳鼻平衡疾患標準治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","notes":"耳鼻平衡疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","ラウセオテ"],"description":"耳鼻平衡疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"耳鼻平衡疾患標準治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は耳鼻咽喉科へ紹介する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"急性期にはめまい急性期管理を実施し、安定期へ移行後は聴平衡リハビリによる維持療法を継続する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"未治療例では生活機能低下を合併する例が散見されるため、定期的な合併症スクリーニング による経過観察が重要である。 (架空)","prevention":["騒音曝露の低減","耳毒性薬剤の確認"],"related_drug_ids":["drug_0118"],"related_disease_ids":["disease_0027"],"revised_at":"2026-03-22","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
