INSERT INTO diseases(public_id, data) VALUES ('disease_0033', $seed_json$
{"id":"disease_0033","name":"ウォウ","name_kana":"ウォウ","name_english":"w'Ou","icd10_chapter":"chapter_ix","medical_department":["cardiology","gynecology"],"chronicity":"chronic","infectious":false,"synonyms":["エイフヴァ","フレイラク","ゲク"],"summary":"ウォウは、心機能の低下を特徴とする急性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":39.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 39 (架空)"},"onset_age_range":{"min_age_years":33,"max_age_years":52,"label":"33-52 代"},"sex_ratio":{"male_ratio":1,"female_ratio":1,"note":"架空比率"},"risk_factors":["運動不足","運動不足","高血圧"]},"etiology":"ウォウは、心機能の低下を特徴とする慢性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["発熱","息切れ","疼痛","食欲不振"],"associated_symptoms":["不眠","下痢"],"onset_pattern":"intermittent"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 循環器疾患に特徴的な検査異常\n- 補助項目: 心エコー検査の補助所見\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 循環器疾患に特徴的な検査異常\n- 補助項目: 心血管関連指標の軽度異常\n(架空)"],"supporting":["本基準は架空値であり、実臨床の診断には使用しない。**循環器疾患に特徴的な検査異常** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)","循環器疾患評価パネル による所見と血行動態異常所見 の組み合わせで判定する。除外診断として循環器疾患に類似する別疾患を除外することが必要。 (架空)"],"notes":"心エコー検査 による所見と心血管機能の変化 の組み合わせで判定する。除外診断として呼吸器由来の胸部症状を除外することが必要。 (架空)"},"required_exams":[{"name":"問診票","category":"imaging","typical_finding":"ゼルンウェ (架空)","reference_range":"アロオムレイ (架空)"},{"name":"内視鏡検査","category":"interview","typical_finding":"グニル (架空)","reference_range":"スイネイ (架空)"},{"name":"MRI検査","category":"blood_test","typical_finding":"ゼルンウェ (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":{"grading_system":"タンクエアイ","grades":[{"label":"グブググ","criteria":"重症度の判定には血行動態スコア を用いる。55 点 を超える例では専門チーム介入 を推奨する (架空)。","recommended_action":"重症度の判定には血行動態スコア を用いる。50 点 を超える例では専門チーム介入 を推奨する (架空)。"},{"label":"クオンフス","criteria":"重症度分類は循環器疾患臨床ステージ分類 (架空)に準拠し、**4 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"循環器疾患重症度分類 (架空) による評価で緊急介入域 以上に該当する場合は、入院加療を考慮する。 (架空)"},{"label":"クオンフス","criteria":"重症度分類は循環器疾患重症度分類 (架空)に準拠し、**4 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"重症度分類は循環器疾患臨床ステージ分類 (架空)に準拠し、**5 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"}]},"differential_diagnoses":["メイアンクス"],"complications":["イエヴィルアダ","ドンイルセ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["イクルエ","ワチウェ"],"description":"標準治療は循環器疾患管理を中心とし、症状に応じて心臓リハビリを併用する。治療開始から16 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["ラウセオテ","ワチウェ"],"description":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は心血管リスク管理による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は循環器疾患管理を中心とし、症状に応じて生活機能支援を併用する。治療開始から14 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の循環器疾患再燃率 は**約 84.5%** と報告される (架空)。","prevention":["運動習慣の維持"],"related_drug_ids":["drug_0044","drug_0034"],"related_disease_ids":["disease_0008","disease_0038"],"revised_at":"2026-03-21","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
