INSERT INTO diseases(public_id, data) VALUES ('disease_0034', $seed_json$
{"id":"disease_0034","name":"ファイェストイ","name_kana":"ファイェストイ","name_english":"Fay'Esti","icd10_chapter":"chapter_ix","medical_department":["cardiology","ophthalmology"],"chronicity":"chronic","infectious":false,"synonyms":["ジャザン"],"summary":"ファイェストイは末梢血管系に発現する病態で、急性発症の経過を呈する。推定有病率は人口 10 万対 39 (架空)。","epidemiology":{"prevalence":{"rate":6.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 6 (架空)"},"onset_age_range":{"min_age_years":20,"max_age_years":36,"label":"20-36 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["糖代謝異常","家族歴"]},"etiology":"ファイェストイは循環器疾患に分類される疾患群で、シトを主訴に受診する例が多い。確定診断には**心エコー検査** を用いる。 (架空)","symptoms":{"main_symptoms":["体重減少","頭痛","倦怠感","動悸"],"associated_symptoms":["浮腫","便秘","めまい"],"onset_pattern":"subacute"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**循環器疾患に特徴的な検査異常** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)","心電図検査 による所見と心血管機能の変化 の組み合わせで判定する。除外診断として循環器疾患に類似する別疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**循環器疾患に特徴的な検査異常** を満たし、かつ5 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["心電図検査 による所見と循環器疾患に整合する身体所見 の組み合わせで判定する。除外診断として循環器疾患に類似する別疾患を除外することが必要。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**循環器疾患に特徴的な検査異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"MRI検査","category":"imaging","typical_finding":"スイケアクテル (架空)","reference_range":"ショウチョン (架空)"},{"name":"心電図","category":"pathology","typical_finding":"ラズイド (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":{"grading_system":"タンクエアイ","grades":[{"label":"クオンフス","criteria":"重症度の判定には総合臨床重症度スコア を用いる。30 点 を超える例では専門チーム介入 を推奨する (架空)。","recommended_action":"循環器疾患臨床ステージ分類 (架空) による評価で高度心血管障害域 以上に該当する場合は、入院加療を考慮する。 (架空)"},{"label":"ディヴィルスチャ","criteria":"循環器疾患臨床ステージ分類 (架空) による評価で循環器疾患重症域 以上に該当する場合は、入院加療を考慮する。 (架空)","recommended_action":"循環器疾患重症度分類 (架空) による評価で循環器疾患重症域 以上に該当する場合は、入院加療を考慮する。 (架空)"}]},"differential_diagnoses":["ムクオウォルド","ラメサ"],"complications":["ジオル","クレアラアフィ","クレアラアンクス"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","ジオエナ"],"description":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"循環器疾患管理 を第一選択とする。効果不十分例では高度循環器治療を追加し、改善が乏しい場合は循環器内科へ紹介する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"循環器標準治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の心血管イベント回避率 は**約 70.0%** と報告される (架空)。","prevention":["血圧管理","脂質管理"],"related_drug_ids":["drug_0037"],"related_disease_ids":["disease_0045"],"revised_at":"2026-03-20","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0035', $seed_json$
{"id":"disease_0035","name":"ルチルム","name_kana":"ルチルム","name_english":"rchi'Rm","icd10_chapter":"chapter_ix","medical_department":["cardiology","surgery"],"chronicity":"chronic","infectious":false,"synonyms":["アラウセ","ベクウ"],"summary":"ルチルムは、血行動態の変化を特徴とする慢性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":47.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 47 (架空)"},"onset_age_range":{"min_age_years":44,"max_age_years":53,"label":"44-53 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["運動不足","運動不足","脂質異常"]},"etiology":"ルチルムは循環器疾患に分類される疾患群で、ルクライフォシを主訴に受診する例が多い。確定診断には**心エコー検査** を用いる。 (架空)","symptoms":{"main_symptoms":["食欲不振","疼痛","息切れ"],"associated_symptoms":["めまい","めまい"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["心電図検査 による所見と心血管機能の変化 の組み合わせで判定する。除外診断として呼吸器由来の胸部症状を除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 循環器疾患に特徴的な検査異常\n- 補助項目: 循環器疾患評価スコアの上昇\n(架空)"],"supporting":["本基準は架空値であり、実臨床の診断には使用しない。**血行動態異常を示す中核所見** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)","心エコー検査 による所見と循環器疾患に整合する身体所見 の組み合わせで判定する。除外診断として呼吸器由来の胸部症状を除外することが必要。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**心電図検査の主要異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"心電図","category":"imaging","typical_finding":"ンウ (架空)","reference_range":"アロオムレイ (架空)"},{"name":"内視鏡検査","category":"blood_test","typical_finding":"クオアマ (架空)","reference_range":"スイネイ (架空)"},{"name":"単純X線撮影","category":"pathology","typical_finding":"ラズイド (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":{"grading_system":"タンクエアイ","grades":[{"label":"ユルヴギル","criteria":"重症度の判定には血行動態スコア を用いる。40 点 を超える例では入院管理の検討 を推奨する (架空)。","recommended_action":"重症度分類は循環器疾患臨床ステージ分類 (架空)に準拠し、**3 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"},{"label":"ウトロウ","criteria":"重症度分類は循環器疾患重症度分類 (架空)に準拠し、**5 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"重症度分類は循環器疾患重症度分類 (架空)に準拠し、**5 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"},{"label":"ウトロウ","criteria":"循環器疾患重症度分類 (架空) による評価で高度心血管障害域 以上に該当する場合は、入院加療を考慮する。 (架空)","recommended_action":"重症度分類は循環器疾患臨床ステージ分類 (架空)に準拠し、**3 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"}]},"differential_diagnoses":["ドイェクイ","ムンクヘ"],"complications":["ルクライガ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ジオエナ","ワチウェ"],"description":"標準治療は循環器疾患管理を中心とし、症状に応じて生活機能支援を併用する。治療開始から2 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["ラウセオテ","ウセ"],"description":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は循環器疾患維持管理による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は循環器疾患標準治療を中心とし、症状に応じて心臓リハビリを併用する。治療開始から20 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の機能維持率 は**約 62.5%** と報告される (架空)。","prevention":["心血管検診"],"related_drug_ids":["drug_0042","drug_0032"],"related_disease_ids":["disease_0018","disease_0012"],"revised_at":"2026-03-19","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
