INSERT INTO diseases(public_id, data) VALUES ('disease_0036', $seed_json$
{"id":"disease_0036","name":"イメイ","name_kana":"イメイ","name_english":"I'Mei","icd10_chapter":"chapter_ix","medical_department":["cardiology","endocrinology"],"chronicity":"chronic","infectious":false,"synonyms":["シラ","ラメディヴィ","アクオル"],"summary":"イメイは循環器系に発現する病態で、緩徐発症の経過を呈する。推定有病率は人口 10 万対 4 (架空)。","epidemiology":{"prevalence":{"rate":12.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 12 (架空)"},"onset_age_range":{"min_age_years":58,"max_age_years":64,"label":"58-64 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["糖代謝異常","糖代謝異常"]},"etiology":"イメイは、血管抵抗の上昇を特徴とする慢性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["動悸","倦怠感","頭痛","体重減少"],"associated_symptoms":["便秘","便秘","浮腫"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 心電図検査の主要異常\n- 補助項目: 心血管関連指標の軽度異常\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 血行動態異常を示す中核所見\n- 補助項目: 循環器疾患評価スコアの上昇\n(架空)","循環器疾患評価パネル による所見と心血管機能の変化 の組み合わせで判定する。除外診断として循環器疾患に類似する別疾患を除外することが必要。 (架空)"],"supporting":["本基準は架空値であり、実臨床の診断には使用しない。**循環器疾患に特徴的な検査異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"循環器疾患評価パネル による所見と血行動態異常所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"},"required_exams":[{"name":"問診票","category":"imaging","typical_finding":"グニル (架空)","reference_range":"ロジアル (架空)"},{"name":"CT検査","category":"blood_test","typical_finding":"ラズイド (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":{"grading_system":"ライイル","grades":[{"label":"ディヴィルスチャ","criteria":"重症度分類は循環器疾患重症度分類 (架空)に準拠し、**4 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"重症度の判定には血行動態スコア を用いる。75 点 を超える例では集中循環管理 を推奨する (架空)。"},{"label":"ウトロウ","criteria":"循環器疾患臨床ステージ分類 (架空) による評価で高度心血管障害域 以上に該当する場合は、入院加療を考慮する。 (架空)","recommended_action":"重症度の判定には総合臨床重症度スコア を用いる。80 点 を超える例では専門チーム介入 を推奨する (架空)。"}]},"differential_diagnoses":["タドジャ"],"complications":["シショウェウレ","ヤス","トテイ"],"treatments":{"pharmacological":[{"drug_category":"イェ","drug_ids":[],"indication":"循環器疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","notes":"急性期には血行動態安定化を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","イクルエ"],"description":"循環器疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"循環器疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"急性期には血行動態安定化を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"未治療例では心不全増悪を合併する例が散見されるため、定期的な心エコー検査 による経過観察が重要である。 (架空)","prevention":["食塩摂取の調整","血圧管理"],"related_drug_ids":["drug_0027"],"related_disease_ids":["disease_0007"],"revised_at":"2026-03-18","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
