INSERT INTO diseases(public_id, data) VALUES ('disease_0037', $seed_json$
{"id":"disease_0037","name":"リイサアルク","name_kana":"リイサアルク","name_english":"liit'Hark","icd10_chapter":"chapter_ix","medical_department":["cardiology","internal_medicine"],"chronicity":"chronic","infectious":false,"synonyms":["ムナクテル"],"summary":"リイサアルクは心血管疾患に分類される疾患群で、ルクライエラスを主訴に受診する例が多い。確定診断には**心電図検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":3.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 3 (架空)"},"onset_age_range":{"min_age_years":46,"max_age_years":53,"label":"46-53 代"},"sex_ratio":{"male_ratio":1,"female_ratio":1,"note":"架空比率"},"risk_factors":["運動不足","高血圧","脂質異常"]},"etiology":"リイサアルクは心血管系に発現する病態で、緩徐発症の経過を呈する。推定有病率は人口 10 万対 31 (架空)。","symptoms":{"main_symptoms":["疼痛","食欲不振","発熱","息切れ","疼痛"],"associated_symptoms":["不眠","発汗"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**循環器疾患に特徴的な検査異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 心電図検査の主要異常\n- 補助項目: 循環器疾患評価スコアの上昇\n(架空)"],"supporting":["心電図検査 による所見と循環器疾患に整合する身体所見 の組み合わせで判定する。除外診断として循環器疾患に類似する別疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**心電図検査の主要異常** を満たし、かつ5 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"循環器疾患評価パネル による所見と心血管機能の変化 の組み合わせで判定する。除外診断として呼吸器由来の胸部症状を除外することが必要。 (架空)"},"required_exams":[{"name":"心電図","category":"imaging","typical_finding":"ンウ (架空)","reference_range":"アロオムレイ (架空)"},{"name":"CT検査","category":"imaging","typical_finding":"スイケアクテル (架空)","reference_range":"ショウチョン (架空)"},{"name":"問診票","category":"interview","typical_finding":"ンウ (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":{"grading_system":"リンググニル","grades":[{"label":"グブググ","criteria":"循環器疾患臨床ステージ分類 (架空) による評価で高度心血管障害域 以上に該当する場合は、入院加療を考慮する。 (架空)","recommended_action":"重症度の判定には心血管機能スコア を用いる。70 点 を超える例では集中循環管理 を推奨する (架空)。"},{"label":"グブググ","criteria":"心血管機能重症度分類 (架空) による評価で循環器疾患重症域 以上に該当する場合は、入院加療を考慮する。 (架空)","recommended_action":"循環器疾患臨床ステージ分類 (架空) による評価で循環器疾患重症域 以上に該当する場合は、入院加療を考慮する。 (架空)"},{"label":"クオンフス","criteria":"循環器疾患臨床ステージ分類 (架空) による評価で緊急介入域 以上に該当する場合は、入院加療を考慮する。 (架空)","recommended_action":"重症度分類は循環器疾患重症度分類 (架空)に準拠し、**5 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"}]},"differential_diagnoses":["アレテアルトイ"],"complications":["ルクト","デスメイ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["イクルエ","ワチテル"],"description":"急性期には循環器疾患急性期プロトコルを実施し、安定期へ移行後は循環器疾患維持管理による維持療法を継続する。 (架空)"},{"heading":"運動療法","items":["ジオエナ","ワチウェ"],"description":"標準治療は循環器疾患管理を中心とし、症状に応じて心臓リハビリを併用する。治療開始から20 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"循環器疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"本疾患の予後は循環器疾患の初期重症度 に大きく左右される。**早期診断** を満たす症例では心機能維持 が期待できる。 (架空)","prevention":["禁煙支援"],"related_drug_ids":["drug_0044","drug_0030"],"related_disease_ids":["disease_0020","disease_0058"],"revised_at":"2026-03-17","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0038', $seed_json$
{"id":"disease_0038","name":"トル","name_kana":"トル","name_english":"t'l","icd10_chapter":"chapter_ix","medical_department":["cardiology","pediatrics"],"chronicity":"chronic","infectious":false,"synonyms":["ヨンスエ"],"summary":"トルは循環器疾患に分類される疾患群で、ダアスを主訴に受診する例が多い。確定診断には**心エコー検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":48.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 48 (架空)"},"onset_age_range":{"min_age_years":50,"max_age_years":70,"label":"50-70 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["家族歴","家族歴"]},"etiology":"トルは循環器系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 46 (架空)。","symptoms":{"main_symptoms":["倦怠感","動悸","体重減少","頭痛","倦怠感"],"associated_symptoms":["下痢","下痢","浮腫"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 心電図検査の主要異常\n- 補助項目: 循環器疾患評価スコアの上昇\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 循環器疾患に特徴的な検査異常\n- 補助項目: 心エコー検査の補助所見\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 心電図検査の主要異常\n- 補助項目: 心エコー検査の補助所見\n(架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 心電図検査の主要異常\n- 補助項目: 心血管関連指標の軽度異常\n(架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 心電図検査の主要異常\n- 補助項目: 循環器疾患評価スコアの上昇\n(架空)"},"required_exams":[{"name":"単純X線撮影","category":"imaging","typical_finding":"クオアマ (架空)","reference_range":"ショウチョン (架空)"},{"name":"MRI検査","category":"interview","typical_finding":"ンウ (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":{"grading_system":"タンクエアイ","grades":[{"label":"ウトロウ","criteria":"重症度分類は循環器疾患臨床ステージ分類 (架空)に準拠し、**4 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"循環器疾患重症度分類 (架空) による評価で緊急介入域 以上に該当する場合は、入院加療を考慮する。 (架空)"},{"label":"ディヴィルスチャ","criteria":"重症度の判定には総合臨床重症度スコア を用いる。50 点 を超える例では集中循環管理 を推奨する (架空)。","recommended_action":"循環器疾患重症度分類 (架空) による評価で循環器疾患重症域 以上に該当する場合は、入院加療を考慮する。 (架空)"}]},"differential_diagnoses":["エスクアルム"],"complications":["クレアララ","ジオワチ","ジオアクオメル"],"treatments":{"pharmacological":[{"drug_category":"イェ","drug_ids":[],"indication":"標準治療は循環器疾患管理を中心とし、症状に応じて心臓リハビリを併用する。治療開始から18 週間 後に効果判定を行う。 (架空)","notes":"標準治療は循環器疾患管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から6 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ウセ","ジオエナ"],"description":"循環器疾患管理 を第一選択とする。効果不十分例では高度循環器治療を追加し、改善が乏しい場合は循環器内科へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"循環器標準治療 を第一選択とする。効果不十分例では高度循環器治療を追加し、改善が乏しい場合は循環器内科へ紹介する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"急性期には循環器疾患急性期プロトコルを実施し、安定期へ移行後は循環器疾患維持管理による維持療法を継続する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"本疾患の予後は血行動態の安定性 に大きく左右される。**治療継続性が良好** を満たす症例では心機能維持 が期待できる。 (架空)","prevention":["脂質管理","食塩摂取の調整"],"related_drug_ids":["drug_0037"],"related_disease_ids":["disease_0057"],"revised_at":"2026-03-16","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
