INSERT INTO diseases(public_id, data) VALUES ('disease_0039', $seed_json$
{"id":"disease_0039","name":"ベグイ","name_kana":"ベグイ","name_english":"be'Guy","icd10_chapter":"chapter_ix","medical_department":["cardiology","otolaryngology"],"chronicity":"chronic","infectious":false,"synonyms":["クトクオンフ"],"summary":"ベグイは、血行動態の変化を特徴とする慢性疾患である。成人に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":49.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 49 (架空)"},"onset_age_range":{"min_age_years":27,"max_age_years":40,"label":"27-40 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["脂質異常","脂質異常","高血圧"]},"etiology":"ベグイは心血管系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 38 (架空)。","symptoms":{"main_symptoms":["息切れ","発熱","食欲不振","疼痛","息切れ"],"associated_symptoms":["悪心","めまい"],"onset_pattern":"intermittent"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 血行動態異常を示す中核所見\n- 補助項目: 循環器疾患評価スコアの上昇\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**循環器疾患に特徴的な検査異常** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 循環器疾患に特徴的な検査異常\n- 補助項目: 循環器疾患評価スコアの上昇\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**心電図検査の主要異常** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**心電図検査の主要異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"内視鏡検査","category":"imaging","typical_finding":"ラズイド (架空)","reference_range":"クンレカ (架空)"},{"name":"心電図","category":"imaging","typical_finding":"スイケアクテル (架空)","reference_range":"ショウチョン (架空)"},{"name":"MRI検査","category":"imaging","typical_finding":"ンウ (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":{"grading_system":"シフィク","grades":[{"label":"ウトロウ","criteria":"重症度分類は心血管機能重症度分類 (架空)に準拠し、**3 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"重症度分類は循環器疾患臨床ステージ分類 (架空)に準拠し、**5 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"},{"label":"クオンフス","criteria":"重症度分類は循環器疾患重症度分類 (架空)に準拠し、**3 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"心血管機能重症度分類 (架空) による評価で高度心血管障害域 以上に該当する場合は、入院加療を考慮する。 (架空)"},{"label":"ユルヴギル","criteria":"重症度分類は心血管機能重症度分類 (架空)に準拠し、**3 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"重症度分類は心血管機能重症度分類 (架空)に準拠し、**4 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"}]},"differential_diagnoses":["グライエル","ラメサイ","クトルニル"],"complications":["ジオゼルン","イルゼルン"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ラウセオテ","ワチテル"],"description":"急性期には循環器疾患急性期プロトコルを実施し、安定期へ移行後は循環器疾患維持管理による維持療法を継続する。 (架空)"},{"heading":"運動療法","items":["ジオエナ","ワチテル"],"description":"標準治療は循環器標準治療を中心とし、症状に応じて心臓リハビリを併用する。治療開始から10 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は循環器疾患標準治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から8 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の循環器疾患再燃率 は**約 61.0%** と報告される (架空)。","prevention":["禁煙支援"],"related_drug_ids":["drug_0038","drug_0044"],"related_disease_ids":["disease_0030","disease_0048"],"revised_at":"2026-03-15","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0040', $seed_json$
{"id":"disease_0040","name":"チレス","name_kana":"チレス","name_english":"Chil'Es","icd10_chapter":"chapter_ix","medical_department":["cardiology","otolaryngology"],"chronicity":"chronic","infectious":false,"synonyms":["オーウルクエ","アカ"],"summary":"チレスは循環器系に発現する病態で、緩徐発症の経過を呈する。推定有病率は人口 10 万対 27 (架空)。","epidemiology":{"prevalence":{"rate":47.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 47 (架空)"},"onset_age_range":{"min_age_years":40,"max_age_years":53,"label":"40-53 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["脂質異常","脂質異常","高血圧"]},"etiology":"チレスは、血管抵抗の上昇を特徴とする急性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["息切れ","発熱","食欲不振","疼痛"],"associated_symptoms":["下痢","発汗"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["心電図検査 による所見と循環器疾患に整合する身体所見 の組み合わせで判定する。除外診断として循環器疾患に類似する別疾患を除外することが必要。 (架空)","循環器疾患評価パネル による所見と血行動態異常所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"supporting":["本基準は架空値であり、実臨床の診断には使用しない。**血行動態異常を示す中核所見** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 血行動態異常を示す中核所見\n- 補助項目: 心エコー検査の補助所見\n(架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 循環器疾患に特徴的な検査異常\n- 補助項目: 心エコー検査の補助所見\n(架空)"},"required_exams":[{"name":"心電図","category":"imaging","typical_finding":"ンウ (架空)","reference_range":"オグンレイ (架空)"},{"name":"CT検査","category":"physiological","typical_finding":"スイケアクテル (架空)","reference_range":"ロジアル (架空)"},{"name":"内視鏡検査","category":"imaging","typical_finding":"ラズイド (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":{"grading_system":"ライイル","grades":[{"label":"グブググ","criteria":"心血管機能重症度分類 (架空) による評価で緊急介入域 以上に該当する場合は、入院加療を考慮する。 (架空)","recommended_action":"重症度の判定には血行動態スコア を用いる。50 点 を超える例では集中循環管理 を推奨する (架空)。"},{"label":"ウトロウ","criteria":"重症度の判定には血行動態スコア を用いる。75 点 を超える例では入院管理の検討 を推奨する (架空)。","recommended_action":"心血管機能重症度分類 (架空) による評価で緊急介入域 以上に該当する場合は、入院加療を考慮する。 (架空)"},{"label":"グブググ","criteria":"重症度分類は循環器疾患重症度分類 (架空)に準拠し、**3 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)","recommended_action":"重症度分類は心血管機能重症度分類 (架空)に準拠し、**3 段階**で評価する。各段階に応じて治療強度を調整する。 (架空)"}]},"differential_diagnoses":["ラメナイ"],"complications":["タンクエウ","クレアラヘク"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["イクルエ","ワチウェ"],"description":"急性期には循環器疾患急性期プロトコルを実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)"},{"heading":"運動療法","items":["イクルエ","ワチウェ"],"description":"標準治療は循環器疾患管理を中心とし、症状に応じて心臓リハビリを併用する。治療開始から12 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"循環器標準治療 を第一選択とする。効果不十分例では高度循環器治療を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"本疾患の予後は治療開始までの期間 に大きく左右される。**治療継続性が良好** を満たす症例では心機能維持 が期待できる。 (架空)","prevention":["心血管検診"],"related_drug_ids":["drug_0034","drug_0032"],"related_disease_ids":["disease_0046","disease_0016"],"revised_at":"2026-03-14","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0041', $seed_json$
{"id":"disease_0041","name":"オクサ","name_kana":"オクサ","name_english":"O'Kuth","icd10_chapter":"chapter_x","medical_department":["internal_medicine","pediatrics"],"chronicity":"chronic","infectious":false,"synonyms":["ニグラ","モニラ","ヤウェ"],"summary":"オクサは気道系に発現する病態で、緩徐発症の経過を呈する。推定有病率は人口 10 万対 14 (架空)。","epidemiology":{"prevalence":{"rate":34.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 34 (架空)"},"onset_age_range":{"min_age_years":32,"max_age_years":52,"label":"32-52 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["加齢","大気汚染曝露"]},"etiology":"オクサは気道系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 18 (架空)。","symptoms":{"main_symptoms":["倦怠感","動悸","体重減少","頭痛","倦怠感"],"associated_symptoms":["下痢","不眠","悪心"],"onset_pattern":"subacute"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 呼吸器疾患に特徴的な検査異常\n- 補助項目: 呼吸器関連指標の軽度異常\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 呼吸機能検査の主要異常\n- 補助項目: 胸部画像検査の補助所見\n(架空)","呼吸器疾患評価パネル による所見と呼吸器機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 呼吸器疾患に特徴的な検査異常\n- 補助項目: 呼吸器関連指標の軽度異常\n(架空)"],"notes":"呼吸機能検査 による所見と呼吸器機能の変化 の組み合わせで判定する。除外診断として循環器由来の息切れを除外することが必要。 (架空)"},"required_exams":[{"name":"内視鏡検査","category":"imaging","typical_finding":"レイラ (架空)","reference_range":"スイネイ (架空)"},{"name":"単純X線撮影","category":"pathology","typical_finding":"サンルクエ (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["タイントレンチャ","ファイメルト","ヤルイト"],"complications":["ルクライアダ","デスアッド"],"treatments":{"pharmacological":[{"drug_category":"イェ","drug_ids":[],"indication":"急性期には酸素化改善療法を実施し、安定期へ移行後は吸入または呼吸管理による維持療法を継続する。 (架空)","notes":"急性期には酸素化改善療法を実施し、安定期へ移行後は呼吸器疾患維持管理による維持療法を継続する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ベショウ","リチ"],"description":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は吸入または呼吸管理による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"呼吸器疾患標準治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は呼吸器内科へ紹介する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"標準治療は呼吸器疾患標準治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から16 週間 後に効果判定を行う。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の呼吸器疾患再燃率 は**約 85.0%** と報告される (架空)。","prevention":["粉じん対策","禁煙支援"],"related_drug_ids":["drug_0113"],"related_disease_ids":["disease_0042"],"revised_at":"2026-03-13","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0042', $seed_json$
{"id":"disease_0042","name":"ムンヌブ","name_kana":"ムンヌブ","name_english":"mn'Nb","icd10_chapter":"chapter_x","medical_department":["internal_medicine","neurology"],"chronicity":"chronic","infectious":false,"synonyms":["ヨンル"],"summary":"ムンヌブは、換気機能の低下を特徴とする亜急性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":35.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 35 (架空)"},"onset_age_range":{"min_age_years":58,"max_age_years":69,"label":"58-69 代"},"sex_ratio":{"male_ratio":1,"female_ratio":1,"note":"架空比率"},"risk_factors":["職業性粉じん曝露","換気不良","換気不良"]},"etiology":"ムンヌブは、換気機能の低下を特徴とする急性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["発熱","息切れ","疼痛","食欲不振"],"associated_symptoms":["浮腫","悪心"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["胸部画像検査 による所見と呼吸器疾患に整合する身体所見 の組み合わせで判定する。除外診断として循環器由来の息切れを除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 呼吸機能検査の主要異常\n- 補助項目: 胸部画像検査の補助所見\n(架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 呼吸器疾患に特徴的な検査異常\n- 補助項目: 胸部画像検査の補助所見\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 呼吸機能検査の主要異常\n- 補助項目: 呼吸器関連指標の軽度異常\n(架空)"],"notes":"呼吸機能検査 による所見と呼吸器疾患に整合する身体所見 の組み合わせで判定する。除外診断として呼吸器疾患に類似する別疾患を除外することが必要。 (架空)"},"required_exams":[{"name":"単純X線撮影","category":"imaging","typical_finding":"メピッス (架空)","reference_range":"オグンレイ (架空)"},{"name":"心電図","category":"physiological","typical_finding":"ルドオンラブレ (架空)","reference_range":"ショウチョン (架空)"},{"name":"問診票","category":"imaging","typical_finding":"メピッス (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["ルジオスレ","ヨルギ","チルセム"],"complications":["シレアヴェ","ドンイモリ","テイクン"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["リチ","ルレル"],"description":"標準治療は呼吸器疾患管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から4 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["クワス","ベショウ"],"description":"標準治療は呼吸器疾患管理を中心とし、症状に応じて呼吸リハビリを併用する。治療開始から22 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には呼吸器疾患急性期プロトコルを実施し、安定期へ移行後は吸入または呼吸管理による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の機能維持率 は**約 58.5%** と報告される (架空)。","prevention":["大気汚染曝露の低減"],"related_drug_ids":["drug_0112","drug_0106"],"related_disease_ids":["disease_0032","disease_0030"],"revised_at":"2026-03-12","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
