INSERT INTO diseases(public_id, data) VALUES ('disease_0044', $seed_json$
{"id":"disease_0044","name":"ルモンリット","name_kana":"ルモンリット","name_english":"Rmon'litt","icd10_chapter":"chapter_x","medical_department":["internal_medicine","emergency"],"chronicity":"chronic","infectious":false,"synonyms":["アンクドイ","オヒルム","タリプロギ"],"summary":"ルモンリットは呼吸器系に発現する病態で、急性発症の経過を呈する。推定有病率は人口 10 万対 18 (架空)。","epidemiology":{"prevalence":{"rate":23.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 23 (架空)"},"onset_age_range":{"min_age_years":23,"max_age_years":40,"label":"23-40 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["職業性粉じん曝露","換気不良","換気不良"]},"etiology":"ルモンリットは肺胞換気系に発現する病態で、急性発症の経過を呈する。推定有病率は人口 10 万対 18 (架空)。","symptoms":{"main_symptoms":["食欲不振","疼痛","息切れ","発熱","食欲不振"],"associated_symptoms":["悪心","悪心"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["呼吸機能検査 による所見と呼吸器疾患に整合する身体所見 の組み合わせで判定する。除外診断として呼吸器疾患に類似する別疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**呼吸機能検査の主要異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["胸部画像検査 による所見と呼吸器機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 呼吸機能検査の主要異常\n- 補助項目: 胸部画像検査の補助所見\n(架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 呼吸機能検査の主要異常\n- 補助項目: 呼吸器関連指標の軽度異常\n(架空)"},"required_exams":[{"name":"内視鏡検査","category":"imaging","typical_finding":"フィレルウム (架空)","reference_range":"クンレカ (架空)"},{"name":"問診票","category":"imaging","typical_finding":"レイラ (架空)","reference_range":"ショウチョン (架空)"},{"name":"血液生化学検査","category":"imaging","typical_finding":"フィレルウム (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["ラウセルスト","リットウケクエプト"],"complications":["イエヴィルスト"],"treatments":{"pharmacological":[{"drug_category":"エイフマジェ","drug_ids":[],"indication":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は呼吸器疾患維持管理による維持療法を継続する。 (架空)","notes":"標準治療は呼吸器疾患管理を中心とし、症状に応じて呼吸リハビリを併用する。治療開始から16 週間 後に効果判定を行う。 (架空)"},{"drug_category":"ガエルルドオン","drug_ids":[],"indication":"急性期には酸素化改善療法を実施し、安定期へ移行後は吸入または呼吸管理による維持療法を継続する。 (架空)","notes":"呼吸器標準治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["アレトカ","シク"],"description":"呼吸器疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は呼吸器内科へ紹介する。 (架空)"},{"heading":"運動療法","items":["クワス","シク"],"description":"呼吸器疾患標準治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"呼吸器疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は呼吸器内科へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では生活機能低下を合併する例が散見されるため、定期的な呼吸機能検査 による経過観察が重要である。 (架空)","prevention":["室内環境調整"],"related_drug_ids":["drug_0106","drug_0108"],"related_disease_ids":["disease_0026","disease_0068"],"revised_at":"2026-03-10","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0045', $seed_json$
{"id":"disease_0045","name":"ラメクウ","name_kana":"ラメクウ","name_english":"Rame'Kuw","icd10_chapter":"chapter_x","medical_department":["internal_medicine","cardiology"],"chronicity":"chronic","infectious":false,"synonyms":["ベクラクイ","ジャタ","ジオニグ"],"summary":"ラメクウは、気道炎症の持続を特徴とする亜急性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":48.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 48 (架空)"},"onset_age_range":{"min_age_years":25,"max_age_years":33,"label":"25-33 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["アレルギー素因","加齢"]},"etiology":"ラメクウは呼吸器疾患に分類される疾患群で、トイムクズを主訴に受診する例が多い。確定診断には**呼吸器疾患評価パネル** を用いる。 (架空)","symptoms":{"main_symptoms":["体重減少","頭痛","倦怠感"],"associated_symptoms":["下痢","下痢","不眠"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**呼吸器疾患に特徴的な検査異常** を満たし、かつ5 項目以上を充足する場合に確定診断とする。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 換気障害を示す中核所見\n- 補助項目: 胸部画像検査の補助所見\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 換気障害を示す中核所見\n- 補助項目: 胸部画像検査の補助所見\n(架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 呼吸機能検査の主要異常\n- 補助項目: 呼吸器疾患評価スコアの上昇\n(架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 呼吸器疾患に特徴的な検査異常\n- 補助項目: 呼吸器疾患評価スコアの上昇\n(架空)"},"required_exams":[{"name":"問診票","category":"imaging","typical_finding":"レイラ (架空)","reference_range":"ショウチョン (架空)"},{"name":"心電図","category":"physiological","typical_finding":"フィレルウム (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["アイスリ","タッドエ"],"complications":["トヘク"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["シク","アレトカ"],"description":"呼吸器標準治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は呼吸器内科へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は吸入または呼吸管理による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"急性期には呼吸器疾患急性期プロトコルを実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"本疾患の予後は酸素化の安定性 に大きく左右される。**禁煙と環境調整** を満たす症例では日常生活の維持 が期待できる。 (架空)","prevention":["禁煙支援","呼吸機能検査"],"related_drug_ids":["drug_0117"],"related_disease_ids":["disease_0021"],"revised_at":"2026-03-09","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
