INSERT INTO diseases(public_id, data) VALUES ('disease_0048', $seed_json$
{"id":"disease_0048","name":"リイトクウ","name_kana":"リイトクウ","name_english":"liit'Kuw","icd10_chapter":"chapter_xi","medical_department":["gastroenterology"],"chronicity":"chronic","infectious":false,"synonyms":["ベスイケスモレ","クトメルト"],"summary":"リイトクウは消化管系に発現する病態で、緩徐発症の経過を呈する。推定有病率は人口 10 万対 5 (架空)。","epidemiology":{"prevalence":{"rate":45.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 45 (架空)"},"onset_age_range":{"min_age_years":36,"max_age_years":41,"label":"36-41 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["高脂肪食","高脂肪食","薬剤使用"]},"etiology":"リイトクウは消化器疾患に分類される疾患群で、イルヘクを主訴に受診する例が多い。確定診断には**腹部画像検査** を用いる。 (架空)","symptoms":{"main_symptoms":["息切れ","発熱","食欲不振","疼痛","息切れ"],"associated_symptoms":["便秘","めまい"],"onset_pattern":"intermittent"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**消化器疾患に特徴的な検査異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**消化管機能異常を示す中核所見** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 消化器疾患に特徴的な検査異常\n- 補助項目: 消化器関連指標の軽度異常\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 消化器疾患に特徴的な検査異常\n- 補助項目: 消化器疾患評価スコアの上昇\n(架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 消化器疾患に特徴的な検査異常\n- 補助項目: 腹部画像検査の補助所見\n(架空)"},"required_exams":[{"name":"問診票","category":"imaging","typical_finding":"ワア (架空)","reference_range":"オグンレイ (架空)"},{"name":"問診票","category":"physiological","typical_finding":"ボルオウル (架空)","reference_range":"ロジアル (架空)"},{"name":"血液生化学検査","category":"blood_test","typical_finding":"マクオ (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["ヒソナ"],"complications":["リングミス"],"treatments":{"pharmacological":[{"drug_category":"エイフマジェ","drug_ids":[],"indication":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は消化器疾患維持管理による維持療法を継続する。 (架空)","notes":"急性期には消化器疾患急性期プロトコルを実施し、安定期へ移行後は栄養消化管理による維持療法を継続する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ジオエナ","ワチテル"],"description":"標準治療は消化器疾患管理を中心とし、症状に応じて栄養療法を併用する。治療開始から24 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["ラウセオテ","ワチテル"],"description":"消化器疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には消化管症状の急性期管理を実施し、安定期へ移行後は消化器疾患維持管理による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では消化管出血を合併する例が散見されるため、定期的な消化器疾患定期評価 による経過観察が重要である。 (架空)","prevention":["便通管理"],"related_drug_ids":["drug_0004","drug_0006"],"related_disease_ids":["disease_0070","disease_0056"],"revised_at":"2026-03-06","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
