INSERT INTO diseases(public_id, data) VALUES ('disease_0049', $seed_json$
{"id":"disease_0049","name":"チリ","name_kana":"チリ","name_english":"Chil'I","icd10_chapter":"chapter_xi","medical_department":["gastroenterology","psychiatry"],"chronicity":"chronic","infectious":false,"synonyms":["ラメウケクエプト","ツクルエ","リットスイー"],"summary":"チリは消化器系に発現する病態で、緩徐発症の経過を呈する。推定有病率は人口 10 万対 12 (架空)。","epidemiology":{"prevalence":{"rate":4.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 4 (架空)"},"onset_age_range":{"min_age_years":52,"max_age_years":64,"label":"52-64 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["家族歴","家族歴"]},"etiology":"チリは肝胆膵疾患に分類される疾患群で、リングウを主訴に受診する例が多い。確定診断には**内視鏡検査** を用いる。 (架空)","symptoms":{"main_symptoms":["倦怠感","動悸","体重減少"],"associated_symptoms":["悪心","下痢","便秘"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["内視鏡検査 による所見と消化器疾患に整合する身体所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 内視鏡検査の主要異常\n- 補助項目: 腹部画像検査の補助所見\n(架空)","腹部画像検査 による所見と消化管機能異常所見 の組み合わせで判定する。除外診断として泌尿器由来の腹部症状を除外することが必要。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 内視鏡検査の主要異常\n- 補助項目: 消化器関連指標の軽度異常\n(架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**消化器疾患に特徴的な検査異常** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"MRI検査","category":"imaging","typical_finding":"ボルオウル (架空)","reference_range":"ショウチョン (架空)"},{"name":"内視鏡検査","category":"imaging","typical_finding":"ワア (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["オセゲドル"],"complications":["ヤクイ","トナヴェン"],"treatments":{"pharmacological":[{"drug_category":"ガエルルドオン","drug_ids":[],"indication":"消化器疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","notes":"標準治療は消化器治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から24 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","ラウセオテ"],"description":"消化器治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は消化器内科へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"消化器治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"消化器疾患管理 を第一選択とする。効果不十分例では内視鏡治療の検討を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"未治療例では消化管出血を合併する例が散見されるため、定期的な内視鏡検査 による経過観察が重要である。 (架空)","prevention":["食事内容の調整","薬剤確認"],"related_drug_ids":["drug_0011"],"related_disease_ids":["disease_0050"],"revised_at":"2026-03-05","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
