INSERT INTO diseases(public_id, data) VALUES ('disease_0050', $seed_json$
{"id":"disease_0050","name":"ホワアルク","name_kana":"ホワアルク","name_english":"w'Hark","icd10_chapter":"chapter_xi","medical_department":["gastroenterology","endocrinology"],"chronicity":"chronic","infectious":false,"synonyms":["クズ","オッド","モンレエ"],"summary":"ホワアルクは消化管機能疾患に分類される疾患群で、リングウを主訴に受診する例が多い。確定診断には**腹部画像検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":24.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 24 (架空)"},"onset_age_range":{"min_age_years":45,"max_age_years":51,"label":"45-51 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["家族歴","家族歴"]},"etiology":"ホワアルクは、消化管運動の異常を特徴とする亜急性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["動悸","倦怠感","頭痛","体重減少"],"associated_symptoms":["悪心","発汗","浮腫"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["腹部画像検査 による所見と消化器疾患に整合する身体所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 消化器疾患に特徴的な検査異常\n- 補助項目: 消化器関連指標の軽度異常\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 消化器疾患に特徴的な検査異常\n- 補助項目: 腹部画像検査の補助所見\n(架空)"],"supporting":["消化器疾患評価パネル による所見と消化器疾患に整合する身体所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"notes":"消化器疾患評価パネル による所見と消化器機能の変化 の組み合わせで判定する。除外診断として泌尿器由来の腹部症状を除外することが必要。 (架空)"},"required_exams":[{"name":"MRI検査","category":"imaging","typical_finding":"モクオン (架空)","reference_range":"ロジアル (架空)"},{"name":"問診票","category":"interview","typical_finding":"ワア (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["カクイ","オセロジ"],"complications":["クレアラトイム","シアイ","ルクライニル"],"treatments":{"pharmacological":[{"drug_category":"ウンドソエ","drug_ids":[],"indication":"標準治療は消化器治療を中心とし、症状に応じて栄養療法を併用する。治療開始から16 週間 後に効果判定を行う。 (架空)","notes":"消化器治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ウセ","イクルエ"],"description":"標準治療は消化器疾患標準治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から10 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"消化器治療 を第一選択とする。効果不十分例では内視鏡治療の検討を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は栄養消化管理による維持療法を継続する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"未治療例では生活機能低下を合併する例が散見されるため、定期的な消化器疾患定期評価 による経過観察が重要である。 (架空)","prevention":["薬剤確認","食事内容の調整"],"related_drug_ids":["drug_0013"],"related_disease_ids":["disease_0007"],"revised_at":"2026-03-04","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
