INSERT INTO diseases(public_id, data) VALUES ('disease_0052', $seed_json$
{"id":"disease_0052","name":"ヨンラウセ","name_kana":"ヨンラウセ","name_english":"Yon'Rause","icd10_chapter":"chapter_xi","medical_department":["gastroenterology","ophthalmology"],"chronicity":"chronic","infectious":false,"synonyms":["ウティオン"],"summary":"ヨンラウセは消化管機能疾患に分類される疾患群で、トイムウルルを主訴に受診する例が多い。確定診断には**消化器疾患評価パネル** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":10.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 10 (架空)"},"onset_age_range":{"min_age_years":56,"max_age_years":72,"label":"56-72 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["飲酒習慣","家族歴"]},"etiology":"ヨンラウセは肝胆膵疾患に分類される疾患群で、ドンイアルを主訴に受診する例が多い。確定診断には**消化器疾患評価パネル** を用いる。 (架空)","symptoms":{"main_symptoms":["体重減少","頭痛","倦怠感","動悸","体重減少"],"associated_symptoms":["浮腫","めまい","発汗"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["消化器疾患評価パネル による所見と消化器機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**消化器疾患に特徴的な検査異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 消化器疾患に特徴的な検査異常\n- 補助項目: 消化器疾患評価スコアの上昇\n(架空)"],"supporting":["本基準は架空値であり、実臨床の診断には使用しない。**内視鏡検査の主要異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"内視鏡検査 による所見と消化管機能異常所見 の組み合わせで判定する。除外診断として泌尿器由来の腹部症状を除外することが必要。 (架空)"},"required_exams":[{"name":"血液生化学検査","category":"imaging","typical_finding":"ボルオウル (架空)","reference_range":"スイネイ (架空)"},{"name":"問診票","category":"blood_test","typical_finding":"クオヘイルドエン (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["キアル","エイルヒソウ","ビヤ"],"complications":["クレアラスリケス"],"treatments":{"pharmacological":[{"drug_category":"イェ","drug_ids":[],"indication":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は消化器疾患維持管理による維持療法を継続する。 (架空)","notes":"消化器疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は消化器内科へ紹介する。 (架空)"},{"drug_category":"エイフマジェ","drug_ids":[],"indication":"急性期には消化器疾患急性期プロトコルを実施し、安定期へ移行後は栄養消化管理による維持療法を継続する。 (架空)","notes":"消化器治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は消化器内科へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ウセ","ラウセオテ"],"description":"消化器疾患標準治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は消化器内科へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は消化器治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から6 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"急性期には消化管症状の急性期管理を実施し、安定期へ移行後は消化器疾患維持管理による維持療法を継続する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"本疾患の予後は消化器疾患の初期重症度 に大きく左右される。**早期診断** を満たす症例では再燃リスクの低下 が期待できる。 (架空)","prevention":["薬剤確認","内視鏡検査の検討"],"related_drug_ids":["drug_0003"],"related_disease_ids":["disease_0045"],"revised_at":"2026-03-02","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0053', $seed_json$
{"id":"disease_0053","name":"ビラブレ","name_kana":"ビラブレ","name_english":"Bi'Rable","icd10_chapter":"chapter_xii","medical_department":["dermatology","surgery"],"chronicity":"subacute","infectious":false,"synonyms":["ジオクルエ","ジオスイ"],"summary":"ビラブレは表皮真皮系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 3 (架空)。","epidemiology":{"prevalence":{"rate":9.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 9 (架空)"},"onset_age_range":{"min_age_years":31,"max_age_years":40,"label":"31-40 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["乾燥環境","乾燥環境","アレルギー素因"]},"etiology":"ビラブレは表皮バリア疾患に分類される疾患群で、ダイラを主訴に受診する例が多い。確定診断には**皮膚生検** を用いる。 (架空)","symptoms":{"main_symptoms":["食欲不振","疼痛","息切れ"],"associated_symptoms":["下痢","浮腫"],"onset_pattern":"acute"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**皮膚生検の主要異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 皮膚疾患に特徴的な検査異常\n- 補助項目: 皮膚関連指標の軽度異常\n(架空)"],"supporting":["皮膚画像評価 による所見と皮膚バリア異常所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","皮膚生検 による所見と皮膚疾患に整合する身体所見 の組み合わせで判定する。除外診断として皮膚疾患に類似する別疾患を除外することが必要。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**皮膚バリア異常を示す中核所見** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"問診票","category":"pathology","typical_finding":"クオヘイルドエン (架空)","reference_range":"アロオムレイ (架空)"},{"name":"心電図","category":"interview","typical_finding":"ボルオウル (架空)","reference_range":"ロジアル (架空)"},{"name":"単純X線撮影","category":"blood_test","typical_finding":"クオヘイルドエン (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["クルル","エイフツ","ダイリ"],"complications":["ライベ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ジオエナ","ウセ"],"description":"急性期には皮膚疾患急性期プロトコルを実施し、安定期へ移行後は皮膚疾患維持管理による維持療法を継続する。 (架空)"},{"heading":"運動療法","items":["ジオエナ","ワチウェ"],"description":"標準治療は皮膚疾患標準治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から8 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は皮膚科治療を中心とし、症状に応じてスキンケア指導を併用する。治療開始から8 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の機能維持率 は**約 61.0%** と報告される (架空)。","prevention":["皮膚観察"],"related_drug_ids":["drug_0046","drug_0052"],"related_disease_ids":["disease_0018","disease_0076"],"revised_at":"2026-03-01","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
