INSERT INTO diseases(public_id, data) VALUES ('disease_0056', $seed_json$
{"id":"disease_0056","name":"クトゲドイ","name_kana":"クトゲドイ","name_english":"Ct'gedy","icd10_chapter":"chapter_xii","medical_department":["dermatology","psychiatry"],"chronicity":"subacute","infectious":false,"synonyms":["ウシアルトエ","エイデノルンクフ"],"summary":"クトゲドイは表皮バリア疾患に分類される疾患群で、トイエヴィルを主訴に受診する例が多い。確定診断には**皮膚画像評価** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":48.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 48 (架空)"},"onset_age_range":{"min_age_years":49,"max_age_years":61,"label":"49-61 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["家族歴","皮膚刺激物曝露"]},"etiology":"クトゲドイは表皮真皮系に発現する病態で、急性発症の経過を呈する。推定有病率は人口 10 万対 41 (架空)。","symptoms":{"main_symptoms":["倦怠感","動悸","体重減少","頭痛"],"associated_symptoms":["便秘","悪心","浮腫"],"onset_pattern":"subacute"},"diagnostic_criteria":{"required":["皮膚疾患評価パネル による所見と皮膚機能の変化 の組み合わせで判定する。除外診断として皮膚疾患に類似する別疾患を除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 皮膚生検の主要異常\n- 補助項目: 皮膚画像評価の補助所見\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**皮膚生検の主要異常** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 皮膚生検の主要異常\n- 補助項目: 皮膚関連指標の軽度異常\n(架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 皮膚バリア異常を示す中核所見\n- 補助項目: 皮膚画像評価の補助所見\n(架空)"},"required_exams":[{"name":"血液生化学検査","category":"pathology","typical_finding":"ボルオウル (架空)","reference_range":"ロジアル (架空)"},{"name":"単純X線撮影","category":"physiological","typical_finding":"クオヘイルドエン (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["ルモンジレイル","ルセクズ","ジオウゼバルイ"],"complications":["シスユ","シアクオメル","ジオクサ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","ラウセオテ"],"description":"皮膚疾患標準治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には皮膚疾患急性期プロトコルを実施し、安定期へ移行後は外用維持療法による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"標準治療は皮膚疾患標準治療を中心とし、症状に応じてスキンケア指導を併用する。治療開始から24 週間 後に効果判定を行う。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"本疾患の予後は治療開始までの期間 に大きく左右される。**治療継続性が良好** を満たす症例では再燃リスクの低下 が期待できる。 (架空)","prevention":["刺激物回避","刺激物回避"],"related_drug_ids":["drug_0049"],"related_disease_ids":["disease_0017"],"revised_at":"2026-02-26","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0057', $seed_json$
{"id":"disease_0057","name":"ジェエンドイヴィ","name_kana":"ジェエンドイヴィ","name_english":"jeen'Divi","icd10_chapter":"chapter_xiii","medical_department":["orthopedics","gastroenterology"],"chronicity":"chronic","infectious":false,"synonyms":["フェイスル","トミト","アレタ"],"summary":"ジェエンドイヴィは、運動器機能の低下を特徴とする慢性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":9.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 9 (架空)"},"onset_age_range":{"min_age_years":59,"max_age_years":64,"label":"59-64 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["肥満","姿勢不良","過負荷動作"]},"etiology":"ジェエンドイヴィは関節系に発現する病態で、緩徐発症の経過を呈する。推定有病率は人口 10 万対 6 (架空)。","symptoms":{"main_symptoms":["息切れ","発熱","食欲不振","疼痛"],"associated_symptoms":["不眠","悪心"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 関節機能低下を示す中核所見\n- 補助項目: 運動器関連指標の軽度異常\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 筋骨格疾患に特徴的な検査異常\n- 補助項目: 炎症マーカー検査の補助所見\n(架空)"],"supporting":["筋骨格疾患評価パネル による所見と筋骨格疾患に整合する身体所見 の組み合わせで判定する。除外診断として筋骨格疾患に類似する別疾患を除外することが必要。 (架空)","筋骨格疾患評価パネル による所見と関節機能低下所見 の組み合わせで判定する。除外診断として神経由来の運動障害を除外することが必要。 (架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 筋骨格疾患に特徴的な検査異常\n- 補助項目: 炎症マーカー検査の補助所見\n(架空)"},"required_exams":[{"name":"問診票","category":"imaging","typical_finding":"ワア (架空)","reference_range":"アロオムレイ (架空)"},{"name":"MRI検査","category":"physiological","typical_finding":"ボルオウル (架空)","reference_range":"ショウチョン (架空)"},{"name":"内視鏡検査","category":"imaging","typical_finding":"クオヘイルドエン (架空)","reference_range":"アロオムレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["アラク","ダルクエ"],"complications":["トディエ"],"treatments":{"pharmacological":[{"drug_category":"ズイル","drug_ids":[],"indication":"標準治療は筋骨格疾患標準治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から12 週間 後に効果判定を行う。 (架空)","notes":"筋骨格疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["イクルエ","ワチテル"],"description":"急性期には筋骨格疾患急性期プロトコルを実施し、安定期へ移行後は筋骨格疾患維持管理による維持療法を継続する。 (架空)"},{"heading":"運動療法","items":["ラウセオテ","ワチテル"],"description":"標準治療は筋骨格疾患標準治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から18 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には疼痛と炎症の初期管理を実施し、安定期へ移行後は筋骨格疾患維持管理による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では運動器機能不全を合併する例が散見されるため、定期的な合併症スクリーニング による経過観察が重要である。 (架空)","prevention":["関節負荷の低減"],"related_drug_ids":["drug_0086"],"related_disease_ids":["disease_0006","disease_0024"],"revised_at":"2026-02-25","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
