INSERT INTO diseases(public_id, data) VALUES ('disease_0060', $seed_json$
{"id":"disease_0060","name":"ウルルトアヴェン","name_kana":"ウルルトアヴェン","name_english":"Ulll'Taven","icd10_chapter":"chapter_xiii","medical_department":["orthopedics","dermatology"],"chronicity":"chronic","infectious":false,"synonyms":["ベダ","ジオクオル"],"summary":"ウルルトアヴェンは、結合組織の炎症を特徴とする亜急性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":47.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 47 (架空)"},"onset_age_range":{"min_age_years":30,"max_age_years":45,"label":"30-45 代"},"sex_ratio":{"male_ratio":1,"female_ratio":1,"note":"架空比率"},"risk_factors":["過負荷動作","肥満","過負荷動作"]},"etiology":"ウルルトアヴェンは関節系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 6 (架空)。","symptoms":{"main_symptoms":["疼痛","食欲不振","発熱","息切れ","疼痛"],"associated_symptoms":["浮腫","便秘"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["炎症マーカー検査 による所見と運動器機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**関節機能低下を示す中核所見** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["関節画像検査 による所見と筋骨格疾患に整合する身体所見 の組み合わせで判定する。除外診断として筋骨格疾患に類似する別疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**関節画像検査の主要異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"関節画像検査 による所見と関節機能低下所見 の組み合わせで判定する。除外診断として神経由来の運動障害を除外することが必要。 (架空)"},"required_exams":[{"name":"MRI検査","category":"imaging","typical_finding":"ワア (架空)","reference_range":"オグンレイ (架空)"},{"name":"内視鏡検査","category":"interview","typical_finding":"ボルオウル (架空)","reference_range":"スイネイ (架空)"},{"name":"心電図","category":"interview","typical_finding":"ワア (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["ラデ"],"complications":["タンクエギエ","テイノ","リングメ"],"treatments":{"pharmacological":[{"drug_category":"ズイル","drug_ids":[],"indication":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は運動器機能維持による維持療法を継続する。 (架空)","notes":"筋骨格疾患管理 を第一選択とする。効果不十分例では専門リハビリ治療を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"},{"drug_category":"イェ","drug_ids":[],"indication":"筋骨格疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","notes":"標準治療は運動器治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から4 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ラウセオテ","ワチテル"],"description":"急性期には疼痛と炎症の初期管理を実施し、安定期へ移行後は運動器機能維持による維持療法を継続する。 (架空)"},{"heading":"運動療法","items":["ジオエナ","ワチテル"],"description":"急性期には疼痛と炎症の初期管理を実施し、安定期へ移行後は運動器機能維持による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は筋骨格疾患管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から24 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では運動器機能不全を合併する例が散見されるため、定期的な関節画像検査 による経過観察が重要である。 (架空)","prevention":["筋力維持"],"related_drug_ids":["drug_0084","drug_0085"],"related_disease_ids":["disease_0076","disease_0050"],"revised_at":"2026-02-22","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
