INSERT INTO diseases(public_id, data) VALUES ('disease_0061', $seed_json$
{"id":"disease_0061","name":"フォシウェル","name_kana":"フォシウェル","name_english":"foshi'Wel","icd10_chapter":"chapter_xiv","medical_department":["urology"],"chronicity":"chronic","infectious":false,"synonyms":["オフォオ"],"summary":"フォシウェルは腎機能疾患に分類される疾患群で、テイイルを主訴に受診する例が多い。確定診断には**腎機能検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":6.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 6 (架空)"},"onset_age_range":{"min_age_years":38,"max_age_years":52,"label":"38-52 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["薬剤使用","薬剤使用"]},"etiology":"フォシウェルは泌尿器疾患に分類される疾患群で、ドンイイアルを主訴に受診する例が多い。確定診断には**腎機能検査** を用いる。 (架空)","symptoms":{"main_symptoms":["動悸","倦怠感","頭痛"],"associated_symptoms":["不眠","悪心","浮腫"],"onset_pattern":"intermittent"},"diagnostic_criteria":{"required":["尿検査 による所見と腎尿路疾患に整合する身体所見 の組み合わせで判定する。除外診断として腎尿路疾患に類似する別疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**尿検査の主要異常** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 尿検査の主要異常\n- 補助項目: 腎機能検査の補助所見\n(架空)"],"supporting":["腎機能検査 による所見と腎尿路機能の変化 の組み合わせで判定する。除外診断として腎尿路疾患に類似する別疾患を除外することが必要。 (架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 尿検査の主要異常\n- 補助項目: 腎尿路疾患評価スコアの上昇\n(架空)"},"required_exams":[{"name":"単純X線撮影","category":"imaging","typical_finding":"ボルオウル (架空)","reference_range":"スイネイ (架空)"},{"name":"内視鏡検査","category":"pathology","typical_finding":"マクオ (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["ウルルペル"],"complications":["テイクレク","タンクエダソウ","リングクアク"],"treatments":{"pharmacological":[{"drug_category":"ガエルルドオン","drug_ids":[],"indication":"腎尿路疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","notes":"標準治療は腎尿路疾患管理を中心とし、症状に応じて水分塩分指導を併用する。治療開始から6 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","イクルエ"],"description":"急性期には水電解質補正を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は腎尿路管理を中心とし、症状に応じて生活機能支援を併用する。治療開始から12 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"腎尿路疾患標準治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"未治療例では生活機能低下を合併する例が散見されるため、定期的な合併症スクリーニング による経過観察が重要である。 (架空)","prevention":["薬剤確認","水分管理"],"related_drug_ids":["drug_0055"],"related_disease_ids":["disease_0063"],"revised_at":"2026-02-21","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
