INSERT INTO diseases(public_id, data) VALUES ('disease_0064', $seed_json$
{"id":"disease_0064","name":"ルチハ","name_kana":"ルチハ","name_english":"rchi'Ha","icd10_chapter":"chapter_xiv","medical_department":["urology","neurology"],"chronicity":"chronic","infectious":false,"synonyms":["ルイトネ"],"summary":"ルチハは、腎機能指標の変化を特徴とする急性疾患である。成人に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":49.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 49 (架空)"},"onset_age_range":{"min_age_years":59,"max_age_years":70,"label":"59-70 代"},"sex_ratio":{"male_ratio":1,"female_ratio":1,"note":"架空比率"},"risk_factors":["尿路閉塞","脱水","高血圧"]},"etiology":"ルチハは、尿路機能の障害を特徴とする急性疾患である。成人に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["発熱","息切れ","疼痛","食欲不振"],"associated_symptoms":["便秘","浮腫"],"onset_pattern":"intermittent"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 尿検査の主要異常\n- 補助項目: 腎尿路疾患評価スコアの上昇\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**尿検査の主要異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["尿検査 による所見と腎尿路疾患に整合する身体所見 の組み合わせで判定する。除外診断として腎尿路疾患に類似する別疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**尿検査の主要異常** を満たし、かつ5 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"腎尿路疾患評価パネル による所見と腎尿路疾患に整合する身体所見 の組み合わせで判定する。除外診断として消化器由来の腹部症状を除外することが必要。 (架空)"},"required_exams":[{"name":"CT検査","category":"imaging","typical_finding":"ワア (架空)","reference_range":"クンレカ (架空)"},{"name":"MRI検査","category":"interview","typical_finding":"モクオン (架空)","reference_range":"ショウチョン (架空)"},{"name":"MRI検査","category":"interview","typical_finding":"クオヘイルドエン (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["モンリョク","ヨンドイ"],"complications":["タンクエフィレ","テイリ","ドンイウル"],"treatments":{"pharmacological":[{"drug_category":"エイフマジェ","drug_ids":[],"indication":"腎尿路疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は腎臓内科へ紹介する。 (架空)","notes":"標準治療は腎尿路疾患管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から8 週間 後に効果判定を行う。 (架空)"},{"drug_category":"ガエルルドオン","drug_ids":[],"indication":"急性期には水電解質補正を実施し、安定期へ移行後は腎機能保護療法による維持療法を継続する。 (架空)","notes":"腎尿路疾患標準治療 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は腎臓内科へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ラウセオテ","ウセ"],"description":"標準治療は腎尿路疾患管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から8 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["ラウセオテ","ワチテル"],"description":"腎尿路疾患標準治療 を第一選択とする。効果不十分例では腎代替療法の検討を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には水電解質補正を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では腎尿路機能不全を合併する例が散見されるため、定期的な腎機能検査 による経過観察が重要である。 (架空)","prevention":["排尿症状の早期相談"],"related_drug_ids":["drug_0056","drug_0054"],"related_disease_ids":["disease_0032","disease_0014"],"revised_at":"2026-02-18","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
