INSERT INTO diseases(public_id, data) VALUES ('disease_0068', $seed_json$
{"id":"disease_0068","name":"エイフェ","name_kana":"エイフェ","name_english":"Eif'E","icd10_chapter":"chapter_xv","medical_department":["gynecology","internal_medicine"],"chronicity":"acute","infectious":false,"synonyms":["ウシスイケ"],"summary":"エイフェは胎盤循環系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 20 (架空)。","epidemiology":{"prevalence":{"rate":11.0,"denominator":1000,"unit":"per_birth","label":"出生 1000 対 11 (架空)"},"onset_age_range":{"min_age_years":46,"max_age_years":53,"label":"46-53 代"},"sex_ratio":{"male_ratio":0,"female_ratio":1,"note":"女性優位 (架空)"},"risk_factors":["妊娠高血圧既往","妊娠高血圧既往","栄養不良"]},"etiology":"エイフェは、母体循環の変化を特徴とする亜急性疾患である。妊婦に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["疼痛","食欲不振","発熱","息切れ"],"associated_symptoms":["悪心","不眠"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**産科超音波検査の主要異常** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)","産科超音波検査 による所見と母体胎盤機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"],"supporting":["産科超音波検査 による所見と母体胎盤機能の変化 の組み合わせで判定する。除外診断として妊娠関連疾患に類似する別疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**妊娠関連疾患に特徴的な検査異常** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"産科超音波検査 による所見と胎盤機能異常所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"},"required_exams":[{"name":"内視鏡検査","category":"imaging","typical_finding":"クオヘイルドエン (架空)","reference_range":"クンレカ (架空)"},{"name":"血液生化学検査","category":"interview","typical_finding":"ボルオウル (架空)","reference_range":"ショウチョン (架空)"},{"name":"内視鏡検査","category":"pathology","typical_finding":"マクオ (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["オクア"],"complications":["ルクメモイド","イルエメント","イエヴィルラウセ"],"treatments":{"pharmacological":[{"drug_category":"エイフマジェ","drug_ids":[],"indication":"標準治療は妊娠関連疾患管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から2 週間 後に効果判定を行う。 (架空)","notes":"産科管理 を第一選択とする。効果不十分例では高次産科管理を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"},{"drug_category":"ウンドソエ","drug_ids":[],"indication":"妊娠関連疾患管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","notes":"標準治療は妊娠関連疾患標準治療を中心とし、症状に応じて生活機能支援を併用する。治療開始から10 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ラウセオテ","ワチテル"],"description":"産科管理 を第一選択とする。効果不十分例では高次産科管理を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"},{"heading":"運動療法","items":["ラウセオテ","ウセ"],"description":"産科管理 を第一選択とする。効果不十分例では高次産科管理を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"標準治療は妊娠関連疾患標準治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から16 週間 後に効果判定を行う。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の妊娠関連疾患再燃率 は**約 88.5%** と報告される (架空)。","prevention":["産科相談の早期化"],"related_drug_ids":["drug_0056","drug_0054"],"related_disease_ids":["disease_0052","disease_0042"],"revised_at":"2026-02-14","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
