INSERT INTO diseases(public_id, data) VALUES ('disease_0069', $seed_json$
{"id":"disease_0069","name":"モンフィシャ","name_kana":"モンフィシャ","name_english":"mon'Fish","icd10_chapter":"chapter_xvi","medical_department":["pediatrics","endocrinology"],"chronicity":"acute","infectious":false,"synonyms":["ムントアンクエ"],"summary":"モンフィシャは周産期疾患に分類される疾患群で、ダメルクイを主訴に受診する例が多い。確定診断には**血液ガス検査** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":46.0,"denominator":1000,"unit":"per_birth","label":"出生 1000 対 46 (架空)"},"onset_age_range":{"min_age_years":34,"max_age_years":40,"label":"34-40 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["母体合併症","低出生体重"]},"etiology":"モンフィシャは新生児疾患に分類される疾患群で、ヤイーイを主訴に受診する例が多い。確定診断には**新生児診察** を用いる。 (架空)","symptoms":{"main_symptoms":["動悸","倦怠感","頭痛","体重減少","動悸"],"associated_symptoms":["発汗","便秘","浮腫"],"onset_pattern":"relapsing"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 新生児診察の主要異常\n- 補助項目: 新生児疾患評価スコアの上昇\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 新生児診察の主要異常\n- 補助項目: 血液ガス検査の補助所見\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 出生後適応異常を示す中核所見\n- 補助項目: 血液ガス検査の補助所見\n(架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 新生児診察の主要異常\n- 補助項目: 新生児疾患評価スコアの上昇\n(架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 出生後適応異常を示す中核所見\n- 補助項目: 血液ガス検査の補助所見\n(架空)"},"required_exams":[{"name":"内視鏡検査","category":"imaging","typical_finding":"ボルオウル (架空)","reference_range":"ロジアル (架空)"},{"name":"問診票","category":"imaging","typical_finding":"マクオ (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["ルセオルンクフ","ヨイル"],"complications":["タンクエスイケ","シエラス","タンクエアン"],"treatments":{"pharmacological":[{"drug_category":"ガエルルドオン","drug_ids":[],"indication":"新生児疾患管理 を第一選択とする。効果不十分例では新生児集中治療を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","notes":"新生児疾患標準治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ウセ","イクルエ"],"description":"急性期には新生児疾患急性期プロトコルを実施し、安定期へ移行後は新生児疾患維持管理による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"新生児疾患管理 を第一選択とする。効果不十分例では新生児集中治療を追加し、改善が乏しい場合は新生児科へ紹介する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"急性期には新生児疾患急性期プロトコルを実施し、安定期へ移行後は発育フォローによる維持療法を継続する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"本疾患の予後は出生後適応の進行 に大きく左右される。**早期栄養支援** を満たす症例では日常生活の維持 が期待できる。 (架空)","prevention":["体温管理","周産期管理"],"related_drug_ids":["drug_0021"],"related_disease_ids":["disease_0071"],"revised_at":"2026-02-13","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
