INSERT INTO diseases(public_id, data) VALUES ('disease_0072', $seed_json$
{"id":"disease_0072","name":"タリポウルクエ","name_kana":"タリポウルクエ","name_english":"Tarip'Ource","icd10_chapter":"chapter_xvii","medical_department":["pediatrics","urology"],"chronicity":"acute","infectious":false,"synonyms":["シャエヴェラ"],"summary":"タリポウルクエは、形態形成の異常を特徴とする亜急性疾患である。新生児に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":42.0,"denominator":1000,"unit":"per_birth","label":"出生 1000 対 42 (架空)"},"onset_age_range":{"min_age_years":32,"max_age_years":46,"label":"32-46 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["胎児発育不全","母体代謝異常"]},"etiology":"タリポウルクエは発生異常疾患に分類される疾患群で、ヤイーイを主訴に受診する例が多い。確定診断には**遺伝学的検査** を用いる。 (架空)","symptoms":{"main_symptoms":["動悸","倦怠感","頭痛","体重減少","動悸"],"associated_symptoms":["下痢","不眠","めまい"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["本基準は架空値であり、実臨床の診断には使用しない。**先天異常疾患に特徴的な検査異常** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**形態形成異常を示す中核所見** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)","遺伝学的検査 による所見と形態形成異常所見 の組み合わせで判定する。除外診断として先天異常疾患に類似する別疾患を除外することが必要。 (架空)"],"supporting":["遺伝学的検査 による所見と形態形成異常所見 の組み合わせで判定する。除外診断として先天異常疾患に類似する別疾患を除外することが必要。 (架空)"],"notes":"遺伝学的検査 による所見と発生形成機能の変化 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)"},"required_exams":[{"name":"問診票","category":"imaging","typical_finding":"ボルオウル (架空)","reference_range":"ロジアル (架空)"},{"name":"MRI検査","category":"pathology","typical_finding":"クオヘイルドエン (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["リセム","ヤヒソウ"],"complications":["リングソ","ライアク","ルクライペン"],"treatments":{"pharmacological":[{"drug_category":"ガエルルドオン","drug_ids":[],"indication":"先天異常疾患管理 を第一選択とする。効果不十分例では専門外科または遺伝医療を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","notes":"標準治療は先天異常管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から4 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ワチウェ","ラウセオテ"],"description":"標準治療は先天異常疾患標準治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から12 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には合併症初期評価を実施し、安定期へ移行後は発達支援継続による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"先天異常管理 を第一選択とする。効果不十分例では治療強度の段階的調整を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"本疾患の予後は合併症の少なさ に大きく左右される。**早期発達支援** を満たす症例では生活機能獲得 が期待できる。 (架空)","prevention":["遺伝相談","遺伝相談"],"related_drug_ids":["drug_0013"],"related_disease_ids":["disease_0031"],"revised_at":"2026-02-10","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0073', $seed_json$
{"id":"disease_0073","name":"ジオジョケ","name_kana":"ジオジョケ","name_english":"JIO※1'Joke","icd10_chapter":"chapter_xviii","medical_department":["internal_medicine","dermatology"],"chronicity":"subacute","infectious":false,"synonyms":["エイルスホウレンクエ"],"summary":"ジオジョケは、原因未確定の症候を特徴とする慢性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":9.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 9 (架空)"},"onset_age_range":{"min_age_years":40,"max_age_years":55,"label":"40-55 代"},"sex_ratio":{"male_ratio":1,"female_ratio":1,"note":"架空比率"},"risk_factors":["原因未確定状態","生活習慣変化","生活習慣変化"]},"etiology":"ジオジョケは、複数所見の併存を特徴とする慢性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["疼痛","食欲不振","発熱","息切れ","疼痛"],"associated_symptoms":["浮腫","悪心"],"onset_pattern":"acute"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 症状所見分類疾患に特徴的な検査異常\n- 補助項目: 追加スクリーニング検査の補助所見\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**総合臨床評価の主要異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["追加スクリーニング検査 による所見と全身所見機能の変化 の組み合わせで判定する。除外診断として確定分類済み疾患を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**原因未確定所見を示す中核所見** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 総合臨床評価の主要異常\n- 補助項目: 追加スクリーニング検査の補助所見\n(架空)"},"required_exams":[{"name":"MRI検査","category":"interview","typical_finding":"マクオ (架空)","reference_range":"クンレカ (架空)"},{"name":"内視鏡検査","category":"pathology","typical_finding":"モクオン (架空)","reference_range":"スイネイ (架空)"},{"name":"心電図","category":"interview","typical_finding":"クオヘイルドエン (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["ルセイゲト","シャデ"],"complications":["イルフィ"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ラウセオテ","ワチテル"],"description":"標準治療は症状所見分類疾患標準治療を中心とし、症状に応じて生活記録支援を併用する。治療開始から16 週間 後に効果判定を行う。 (架空)"},{"heading":"運動療法","items":["ラウセオテ","ウセ"],"description":"標準治療は症候別管理を中心とし、症状に応じて合併症予防指導を併用する。治療開始から24 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"症状所見分類疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では全身所見機能不全を合併する例が散見されるため、定期的な症状所見分類疾患定期評価 による経過観察が重要である。 (架空)","prevention":["追加検査の実施"],"related_drug_ids":["drug_0119"],"related_disease_ids":["disease_0012","disease_0002"],"revised_at":"2026-02-09","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0074', $seed_json$
{"id":"disease_0074","name":"ラウセリット","name_kana":"ラウセリット","name_english":"Rause'litt","icd10_chapter":"chapter_xviii","medical_department":["internal_medicine","pediatrics"],"chronicity":"subacute","infectious":false,"synonyms":["タインザナ","ウルルモティ","チルクアーナサエル"],"summary":"ラウセリットは全身評価系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 41 (架空)。","epidemiology":{"prevalence":{"rate":48.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 48 (架空)"},"onset_age_range":{"min_age_years":44,"max_age_years":64,"label":"44-64 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["検査未完了","多疾患併存"]},"etiology":"ラウセリットは、原因未確定の症候を特徴とする亜急性疾患である。高齢者に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","symptoms":{"main_symptoms":["倦怠感","動悸","体重減少","頭痛","倦怠感"],"associated_symptoms":["浮腫","浮腫","浮腫"],"onset_pattern":"acute"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 症状所見分類疾患に特徴的な検査異常\n- 補助項目: 症状所見分類疾患評価スコアの上昇\n(架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 総合臨床評価の主要異常\n- 補助項目: 全身所見関連指標の軽度異常\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**原因未確定所見を示す中核所見** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 原因未確定所見を示す中核所見\n- 補助項目: 追加スクリーニング検査の補助所見\n(架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 原因未確定所見を示す中核所見\n- 補助項目: 全身所見関連指標の軽度異常\n(架空)"},"required_exams":[{"name":"心電図","category":"interview","typical_finding":"ヒロト (架空)","reference_range":"ロジアル (架空)"},{"name":"心電図","category":"blood_test","typical_finding":"マクオ (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["フェイマイ","ルモンドア","テロンズ"],"complications":["ドンイグニル","ライブ","トイム"],"treatments":{"pharmacological":[],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","ジオエナ"],"description":"症状所見分類疾患管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は症状所見分類疾患維持管理による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は経過観察による維持療法を継続する。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"早期発見により予後は良好である。診断 5 年後の機能維持率 は**約 60.5%** と報告される (架空)。","prevention":["経過観察","症状変化の早期相談"],"related_drug_ids":["drug_0119"],"related_disease_ids":["disease_0041"],"revised_at":"2026-02-08","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
