INSERT INTO diseases(public_id, data) VALUES ('disease_0075', $seed_json$
{"id":"disease_0075","name":"ウシヨ","name_kana":"ウシヨ","name_english":"Ushi'Yo","icd10_chapter":"chapter_xix","medical_department":["surgery","otolaryngology"],"chronicity":"acute","infectious":false,"synonyms":["リクウ","モンハイス"],"summary":"ウシヨは、急性侵襲反応を特徴とする慢性疾患である。中高年に好発し、近年診断技術の進歩により早期発見例が増加している。 (架空)","epidemiology":{"prevalence":{"rate":49.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 49 (架空)"},"onset_age_range":{"min_age_years":21,"max_age_years":34,"label":"21-34 代"},"sex_ratio":{"male_ratio":3,"female_ratio":1,"note":"架空比率"},"risk_factors":["骨脆弱性","作業中外傷","作業中外傷"]},"etiology":"ウシヨは急性侵襲系に発現する病態で、急性発症の経過を呈する。推定有病率は人口 10 万対 47 (架空)。","symptoms":{"main_symptoms":["息切れ","発熱","食欲不振","疼痛","息切れ"],"associated_symptoms":["発汗","不眠"],"onset_pattern":"intermittent"},"diagnostic_criteria":{"required":["外傷損傷疾患評価パネル による所見と急性損傷所見所見 の組み合わせで判定する。除外診断として外傷損傷疾患に類似する別疾患を除外することが必要。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 急性損傷所見を示す中核所見\n- 補助項目: 外傷損傷疾患評価スコアの上昇\n(架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 損傷部位画像検査の主要異常\n- 補助項目: 損傷組織関連指標の軽度異常\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**損傷部位画像検査の主要異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"外傷損傷疾患評価パネル による所見と外傷損傷疾患に整合する身体所見 の組み合わせで判定する。除外診断として非外傷性急性症状を除外することが必要。 (架空)"},"required_exams":[{"name":"心電図","category":"imaging","typical_finding":"マクオ (架空)","reference_range":"クンレカ (架空)"},{"name":"内視鏡検査","category":"pathology","typical_finding":"ヒロト (架空)","reference_range":"スイネイ (架空)"},{"name":"心電図","category":"pathology","typical_finding":"マクオ (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["ニグコル","エイトラク","ルジオルイズ"],"complications":["イルドイ"],"treatments":{"pharmacological":[{"drug_category":"ズイル","drug_ids":[],"indication":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は機能回復管理による維持療法を継続する。 (架空)","notes":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は外傷損傷疾患維持管理による維持療法を継続する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ラウセオテ","ワチウェ"],"description":"外傷治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は救急科へ紹介する。 (架空)"},{"heading":"運動療法","items":["イクルエ","ウセ"],"description":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は機能回復管理による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"外傷損傷疾患標準治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"本疾患の予後は初期処置までの時間 に大きく左右される。**早期外傷対応** を満たす症例では日常生活の維持 が期待できる。 (架空)","prevention":["外傷後フォロー"],"related_drug_ids":["drug_0092","drug_0002"],"related_disease_ids":["disease_0030","disease_0064"],"revised_at":"2026-02-07","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
