INSERT INTO diseases(public_id, data) VALUES ('disease_0076', $seed_json$
{"id":"disease_0076","name":"セムト","name_kana":"セムト","name_english":"Sem'to","icd10_chapter":"chapter_xix","medical_department":["surgery","orthopedics"],"chronicity":"acute","infectious":false,"synonyms":["シャクア"],"summary":"セムトは急性侵襲系に発現する病態で、急性発症の経過を呈する。推定有病率は人口 10 万対 22 (架空)。","epidemiology":{"prevalence":{"rate":4.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 4 (架空)"},"onset_age_range":{"min_age_years":20,"max_age_years":30,"label":"20-30 代"},"sex_ratio":{"male_ratio":4,"female_ratio":1,"note":"架空比率"},"risk_factors":["スポーツ外傷","交通外傷"]},"etiology":"セムトは外傷疾患に分類される疾患群で、デスドウを主訴に受診する例が多い。確定診断には**神経血管評価** を用いる。 (架空)","symptoms":{"main_symptoms":["頭痛","体重減少","動悸"],"associated_symptoms":["悪心","浮腫","便秘"],"onset_pattern":"intermittent"},"diagnostic_criteria":{"required":["損傷部位画像検査 による所見と外傷損傷疾患に整合する身体所見 の組み合わせで判定する。除外診断として非外傷性急性症状を除外することが必要。 (架空)","神経血管評価 による所見と急性損傷所見所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","本基準は架空値であり、実臨床の診断には使用しない。**外傷損傷疾患に特徴的な検査異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 外傷損傷疾患に特徴的な検査異常\n- 補助項目: 外傷損傷疾患評価スコアの上昇\n(架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**外傷損傷疾患に特徴的な検査異常** を満たし、かつ1 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"MRI検査","category":"imaging","typical_finding":"ボルオウル (架空)","reference_range":"ロジアル (架空)"},{"name":"単純X線撮影","category":"physiological","typical_finding":"ワア (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["ウブラス","エイルム"],"complications":["ダプリス","クレアラブラス","シグ"],"treatments":{"pharmacological":[{"drug_category":"イェ","drug_ids":[],"indication":"急性期には損傷部位の初期処置を実施し、安定期へ移行後は機能回復管理による維持療法を継続する。 (架空)","notes":"外傷損傷疾患管理 を第一選択とする。効果不十分例では手術的治療の検討を追加し、改善が乏しい場合は救急科へ紹介する。 (架空)"},{"drug_category":"エイフマジェ","drug_ids":[],"indication":"急性期には外傷損傷疾患急性期プロトコルを実施し、安定期へ移行後は外傷損傷疾患維持管理による維持療法を継続する。 (架空)","notes":"標準治療は外傷損傷疾患管理を中心とし、症状に応じて外傷リハビリを併用する。治療開始から8 週間 後に効果判定を行う。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ワチウェ","ラウセオテ"],"description":"標準治療は外傷損傷疾患管理を中心とし、症状に応じて生活機能支援を併用する。治療開始から22 週間 後に効果判定を行う。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には損傷部位の初期処置を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"標準治療は外傷治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から20 週間 後に効果判定を行う。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"本疾患の予後は初期処置までの時間 に大きく左右される。**早期外傷対応** を満たす症例では日常生活の維持 が期待できる。 (架空)","prevention":["救急相談体制","作業環境調整"],"related_drug_ids":["drug_0009"],"related_disease_ids":["disease_0035"],"revised_at":"2026-02-06","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
$seed_json$::jsonb);
INSERT INTO diseases(public_id, data) VALUES ('disease_0077', $seed_json$
{"id":"disease_0077","name":"ジオテル","name_kana":"ジオテル","name_english":"JIO'Tell","icd10_chapter":"chapter_xx","medical_department":["emergency","neurology"],"chronicity":"acute","infectious":false,"synonyms":["シャモティ"],"summary":"ジオテルは安全リスク評価系に発現する病態で、外因曝露後発症の経過を呈する。推定有病率は人口 10 万対 3 (架空)。","epidemiology":{"prevalence":{"rate":13.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 13 (架空)"},"onset_age_range":{"min_age_years":38,"max_age_years":49,"label":"38-49 代"},"sex_ratio":{"male_ratio":1,"female_ratio":1,"note":"架空比率"},"risk_factors":["危険作業環境","危険作業環境","災害曝露"]},"etiology":"ジオテルは外因評価系に発現する病態で、外因曝露後発症の経過を呈する。推定有病率は人口 10 万対 19 (架空)。","symptoms":{"main_symptoms":["発熱","息切れ","疼痛","食欲不振"],"associated_symptoms":["浮腫","浮腫"],"onset_pattern":"subacute"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 環境要因関連所見を示す中核所見\n- 補助項目: 外因関連状態評価スコアの上昇\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**外因関連状態に特徴的な検査異常** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)"],"supporting":["曝露状況評価 による所見と環境要因関連所見所見 の組み合わせで判定する。除外診断として薬剤性または外因性の類似病態を除外することが必要。 (架空)","曝露状況評価 による所見と環境要因関連所見所見 の組み合わせで判定する。除外診断として内因性疾患を除外することが必要。 (架空)"],"notes":"本基準は架空値であり、実臨床の診断には使用しない。**環境要因関連所見を示す中核所見** を満たし、かつ3 項目以上を充足する場合に確定診断とする。 (架空)"},"required_exams":[{"name":"問診票","category":"interview","typical_finding":"クオヘイルドエン (架空)","reference_range":"クンレカ (架空)"},{"name":"CT検査","category":"blood_test","typical_finding":"モクオン (架空)","reference_range":"スイネイ (架空)"},{"name":"内視鏡検査","category":"pathology","typical_finding":"クオヘイルドエン (架空)","reference_range":"オグンレイ (架空)"}],"severity_grading":null,"differential_diagnoses":["エイルファイ","ルチェル","プリスクオア"],"complications":["ライフォル","タンクエクウ"],"treatments":{"pharmacological":[{"drug_category":"ズイル","drug_ids":[],"indication":"標準治療は外因関連状態標準治療を中心とし、症状に応じて合併症予防指導を併用する。治療開始から18 週間 後に効果判定を行う。 (架空)","notes":"外因リスク管理 を第一選択とする。効果不十分例では専門的安全介入を追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"},{"drug_category":"イェ","drug_ids":[],"indication":"外因リスク管理 を第一選択とする。効果不十分例では専門的安全介入を追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","notes":"外因関連状態標準治療 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は救急科へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ラウセオテ","ウセ"],"description":"外因関連状態管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は地域基幹病院へ紹介する。 (架空)"},{"heading":"運動療法","items":["ジオエナ","ワチウェ"],"description":"外因関連状態管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"外因リスク管理 を第一選択とする。効果不十分例では専門治療への切替えを追加し、改善が乏しい場合は専門医療機関へ紹介する。 (架空)","target":"目標値 1 (架空)"}]},"prognosis":"未治療例では再曝露による悪化を合併する例が散見されるため、定期的な曝露状況評価 による経過観察が重要である。 (架空)","prevention":["安全装備の使用"],"related_drug_ids":["drug_0010","drug_0036"],"related_disease_ids":["disease_0016","disease_0046"],"revised_at":"2026-02-05","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
