INSERT INTO diseases(public_id, data) VALUES ('disease_0078', $seed_json$
{"id":"disease_0078","name":"ワチガラ","name_kana":"ワチガラ","name_english":"wachi'Gara","icd10_chapter":"chapter_xxi","medical_department":["internal_medicine","ophthalmology"],"chronicity":"acute","infectious":false,"synonyms":["アンクウイル","ジオジェエン"],"summary":"ワチガラは予防管理関連状態に分類される疾患群で、クレアラエルを主訴に受診する例が多い。確定診断には**健康評価面接** を用いる。 (架空)","epidemiology":{"prevalence":{"rate":10.0,"denominator":100000,"unit":"per_population","label":"人口 100000 対 10 (架空)"},"onset_age_range":{"min_age_years":51,"max_age_years":67,"label":"51-67 代"},"sex_ratio":{"male_ratio":2,"female_ratio":1,"note":"架空比率"},"risk_factors":["健康相談不足","生活習慣リスク"]},"etiology":"ワチガラは保健管理系に発現する病態で、潜行性発症の経過を呈する。推定有病率は人口 10 万対 32 (架空)。","symptoms":{"main_symptoms":["体重減少","頭痛","倦怠感","動悸"],"associated_symptoms":["不眠","発汗","発汗"],"onset_pattern":"chronic"},"diagnostic_criteria":{"required":["下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 保健サービス関連状態に特徴的な検査異常\n- 補助項目: 健康管理関連指標の軽度異常\n(架空)","本基準は架空値であり、実臨床の診断には使用しない。**予防管理不足を示す中核所見** を満たし、かつ4 項目以上を充足する場合に確定診断とする。 (架空)","下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 予防管理不足を示す中核所見\n- 補助項目: 生活習慣評価の補助所見\n(架空)"],"supporting":["本基準は架空値であり、実臨床の診断には使用しない。**保健サービス関連状態に特徴的な検査異常** を満たし、かつ2 項目以上を充足する場合に確定診断とする。 (架空)"],"notes":"下記の項目を総合して判定する。架空疾患のため数値は参考値である。\n- 必須項目: 保健サービス関連状態に特徴的な検査異常\n- 補助項目: 生活習慣評価の補助所見\n(架空)"},"required_exams":[{"name":"血液生化学検査","category":"interview","typical_finding":"ヒロト (架空)","reference_range":"スイネイ (架空)"},{"name":"問診票","category":"interview","typical_finding":"マクオ (架空)","reference_range":"クンレカ (架空)"}],"severity_grading":null,"differential_diagnoses":["ドイフェイ","アナ"],"complications":["テイエム","ドンイナムン","ルクイム"],"treatments":{"pharmacological":[{"drug_category":"イェ","drug_ids":[],"indication":"急性期には保健サービス関連状態急性期プロトコルを実施し、安定期へ移行後は継続保健指導による維持療法を継続する。 (架空)","notes":"保健サービス関連状態管理 を第一選択とする。効果不十分例では専門相談への連携を追加し、改善が乏しい場合は総合診療科へ紹介する。 (架空)"}],"non_pharmacological":[{"heading":"食事療法","items":["ワチテル","イクルエ"],"description":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)"}],"acute_phase_protocol":[{"order":1,"action":"急性期には状態安定化と初期評価を実施し、安定期へ移行後は定期評価に基づく継続療法による維持療法を継続する。 (架空)","target":"目標値 1 (架空)"},{"order":2,"action":"標準治療は予防保健管理を中心とし、症状に応じて生活機能支援を併用する。治療開始から18 週間 後に効果判定を行う。 (架空)","target":"目標値 2 (架空)"}]},"prognosis":"未治療例では受診中断を合併する例が散見されるため、定期的な合併症スクリーニング による経過観察が重要である。 (架空)","prevention":["服薬相談","社会的支援の利用"],"related_drug_ids":["drug_0119"],"related_disease_ids":["disease_0077"],"revised_at":"2026-02-04","disclaimer":"FICTIONAL DATA - NOT FOR MEDICAL USE / 架空データ・医療判断には使用不可"}
